(13, 1, '📖 Từ vựng: Lời chào & Mẫu câu tự giới thiệu', NULL, 'vocabulary', '[{\"word\":\"Hello\",\"phonetic\":\"\\/h\\u0259\\u02c8lo\\u028a\\/\",\"meaning\":\"Xin ch\\u00e0o (th\\u00e2n m\\u1eadt)\",\"example\":\"Hello, nice to meet you!\"},{\"word\":\"Good morning\",\"phonetic\":\"\\/\\u0261\\u028ad \\u02c8m\\u0254\\u02d0rn\\u026a\\u014b\\/\",\"meaning\":\"Ch\\u00e0o bu\\u1ed5i s\\u00e1ng (tr\\u01b0\\u1edbc 12h tr\\u01b0a)\",\"example\":\"Good morning, class! Please sit down.\"},{\"word\":\"Good afternoon\",\"phonetic\":\"\\/\\u0261\\u028ad \\u02cc\\u00e6ft\\u0259r\\u02c8nu\\u02d0n\\/\",\"meaning\":\"Ch\\u00e0o bu\\u1ed5i chi\\u1ec1u (12h - 18h)\",\"example\":\"Good afternoon, Mr. David.\"},{\"word\":\"Good evening\",\"phonetic\":\"\\/\\u0261\\u028ad \\u02c8i\\u02d0vn\\u026a\\u014b\\/\",\"meaning\":\"Ch\\u00e0o bu\\u1ed5i t\\u1ed1i (sau 18h)\",\"example\":\"Good evening, ladies and gentlemen.\"},{\"word\":\"Nice to meet you\",\"phonetic\":\"\\/na\\u026as tu\\u02d0 mi\\u02d0t ju\\u02d0\\/\",\"meaning\":\"R\\u1ea5t vui \\u0111\\u01b0\\u1ee3c g\\u1eb7p b\\u1ea1n\",\"example\":\"I am Sarah. Nice to meet you!\"},{\"word\":\"Introduce\",\"phonetic\":\"\\/\\u02cc\\u026antr\\u0259\\u02c8dju\\u02d0s\\/\",\"meaning\":\"Gi\\u1edbi thi\\u1ec7u\",\"example\":\"Let me introduce myself. My name is Linh.\"},{\"word\":\"Country\",\"phonetic\":\"\\/\\u02c8k\\u028cntri\\/\",\"meaning\":\"Qu\\u1ed1c gia, \\u0111\\u1ea5t n\\u01b0\\u1edbc\",\"example\":\"Vietnam is a beautiful country.\"},{\"word\":\"Hometown\",\"phonetic\":\"\\/\\u02c8ho\\u028amta\\u028an\\/\",\"meaning\":\"Qu\\u00ea h\\u01b0\\u01a1ng, qu\\u00ea nh\\u00e0\",\"example\":\"My hometown is Da Nang city.\"}]', 1, 10, 1, 1, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 08:07:58'),
(14, 1, '🎬 Video: Kỹ năng Chào hỏi & Tự giới thiệu chuẩn bản xứ', NULL, 'video', '{\"video_url\":\"https:\\/\\/www.youtube.com\\/watch?v=Fw0rdhmsdd0\",\"title\":\"English Greetings & Self Introduction Lesson\",\"description\":\"Trong video n\\u00e0y, gi\\u00e1o vi\\u00ean b\\u1ea3n ng\\u1eef s\\u1ebd h\\u01b0\\u1edbng d\\u1eabn b\\u1ea1n c\\u00e1ch ph\\u00e1t \\u00e2m chu\\u1ea9n c\\u00e1c m\\u1eabu c\\u00e2u ch\\u00e0o h\\u1ecfi h\\u00e0ng ng\\u00e0y, s\\u1ef1 kh\\u00e1c bi\\u1ec7t gi\\u1eefa giao ti\\u1ebfp trang tr\\u1ecdng (formal) v\\u00e0 th\\u00e2n thi\\u1ec7n (informal), c\\u00f9ng ng\\u1eef \\u0111i\\u1ec7u t\\u1ef1 nhi\\u00ean khi b\\u1eaft chuy\\u1ec7n v\\u1edbi ng\\u01b0\\u1eddi n\\u01b0\\u1edbc ngo\\u00e0i.\",\"duration\":\"08:45\"}', 2, 15, 1, 1, NULL, NULL, 'auto_view', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 08:07:59'),
(15, 1, '📐 Ngữ pháp: Đại từ nhân xưng & Động từ TO BE (am / is / are)', NULL, 'grammar', '{\"title\":\"Chuy\\u00ean \\u0111\\u1ec1: \\u0110\\u1ea1i t\\u1eeb nh\\u00e2n x\\u01b0ng & \\u0110\\u1ed9ng t\\u1eeb TO BE \\u1edf Hi\\u1ec7n t\\u1ea1i \\u0111\\u01a1n\",\"explanation\":\"\\u0110\\u1ed9ng t\\u1eeb TO BE c\\u00f3 3 d\\u1ea1ng \\u1edf th\\u00ec Hi\\u1ec7n t\\u1ea1i \\u0111\\u01a1n: am, is, are. N\\u00f3 mang ngh\\u0129a l\\u00e0 \\\"th\\u00ec, l\\u00e0, \\u1edf\\\", d\\u00f9ng \\u0111\\u1ec3 n\\u1ed1i ch\\u1ee7 ng\\u1eef v\\u1edbi danh t\\u1eeb (ngh\\u1ec1 nghi\\u1ec7p, t\\u00ean g\\u1ecdi) ho\\u1eb7c t\\u00ednh t\\u1eeb (t\\u00ednh ch\\u1ea5t, c\\u1ea3m x\\u00fac, qu\\u1ed1c t\\u1ecbch).\",\"rules\":[\"Ch\\u1ee7 ng\\u1eef \\\"I\\\" lu\\u00f4n \\u0111i v\\u1edbi \\\"am\\\" (Vi\\u1ebft t\\u1eaft: I\'m) \\u2192 I am a student.\",\"Ch\\u1ee7 ng\\u1eef s\\u1ed1 \\u00edt \\\"He \\/ She \\/ It \\/ Danh t\\u1eeb s\\u1ed1 \\u00edt\\\" \\u0111i v\\u1edbi \\\"is\\\" (Vi\\u1ebft t\\u1eaft: He\'s, She\'s) \\u2192 She is a doctor.\",\"Ch\\u1ee7 ng\\u1eef s\\u1ed1 nhi\\u1ec1u \\\"You \\/ We \\/ They \\/ Danh t\\u1eeb s\\u1ed1 nhi\\u1ec1u\\\" \\u0111i v\\u1edbi \\\"are\\\" (Vi\\u1ebft t\\u1eaft: You\'re, We\'re) \\u2192 We are from Vietnam.\",\"Th\\u1ec3 ph\\u1ee7 \\u0111\\u1ecbnh (Negative): Th\\u00eam \\\"NOT\\\" sau TO BE \\u2192 S + am\\/is\\/are + not (isn\'t \\/ aren\'t).\",\"Th\\u1ec3 nghi v\\u1ea5n (Question): \\u0110\\u1ea3o TO BE l\\u00ean \\u0111\\u1ea7u c\\u00e2u \\u2192 Am\\/Is\\/Are + S + ...? (Are you ready? \\u2192 Yes, I am \\/ No, I\'m not).\"],\"examples\":[\"Hello! My name is Linh. I am twenty-two years old and I am from Hanoi.\",\"This is Peter. He is my English teacher. He is from the United Kingdom.\",\"Are they your classmates? - Yes, they are. They are very friendly.\",\"I am not tired today. I am excited to learn English!\"]}', 3, 15, 1, 1, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 08:07:59'),
(16, 1, '🎧 Luyện nghe: Cuộc trò chuyện làm quen lần đầu (First Meeting)', NULL, 'audio_listening', '{\"audio_url\":\"https:\\/\\/www.soundhelix.com\\/examples\\/mp3\\/SoundHelix-Song-1.mp3\",\"title\":\"First Meeting at an International Cafe\",\"transcript\":\"David: Excuse me, is this seat taken?\\nSarah: No, it isn\'t. Please have a seat!\\nDavid: Thank you! By the way, my name is David. Nice to meet you.\\nSarah: Hi David! I\'m Sarah. Nice to meet you too.\\nDavid: Are you a student here, Sarah?\\nSarah: Yes, I am. I study Graphic Design. Where are you from?\\nDavid: I\'m from Melbourne, Australia. I\'m currently traveling and learning Vietnamese.\\nSarah: Wow, that\'s awesome! Welcome to Vietnam!\"}', 4, 12, 1, 0, NULL, NULL, 'auto_view', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:28'),
(17, 1, '🎯 Quiz CBT: Kiểm tra kiến thức Bài 1', NULL, 'quiz', '{\"questions\":[{\"question\":\"Ch\\u1ecdn d\\u1ea1ng \\u0111\\u00fang c\\u1ee7a \\u0111\\u1ed9ng t\\u1eeb TO BE \\u0111\\u1ec3 ho\\u00e0n th\\u00e0nh c\\u00e2u: \\\"She _____ an English teacher at my school.\\\"\",\"question_type\":\"mcq\",\"options\":[\"am\",\"is\",\"are\",\"be\"],\"answer\":1,\"correct_answer\":\"is\",\"explanation\":\"Ch\\u1ee7 ng\\u1eef \\\"She\\\" l\\u00e0 ng\\u00f4i th\\u1ee9 3 s\\u1ed1 \\u00edt n\\u00ean \\u0111\\u1ed9ng t\\u1eeb TO BE t\\u01b0\\u01a1ng \\u1ee9ng \\u1edf th\\u00ec hi\\u1ec7n t\\u1ea1i \\u0111\\u01a1n l\\u00e0 \\\"is\\\".\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"Khi g\\u1eb7p m\\u1ed9t ng\\u01b0\\u1eddi b\\u1ea1n m\\u1edbi v\\u00e0o l\\u00fac 9 gi\\u1edd s\\u00e1ng, c\\u00e2u ch\\u00e0o n\\u00e0o sau \\u0111\\u00e2y l\\u00e0 ph\\u00f9 h\\u1ee3p v\\u00e0 l\\u1ecbch s\\u1ef1 nh\\u1ea5t?\",\"question_type\":\"mcq\",\"options\":[\"Good afternoon\",\"Good evening\",\"Good morning\",\"Good night\"],\"answer\":2,\"correct_answer\":\"Good morning\",\"explanation\":\"\\\"Good morning\\\" \\u0111\\u01b0\\u1ee3c d\\u00f9ng \\u0111\\u1ec3 ch\\u00e0o h\\u1ecfi t\\u1eeb s\\u00e1ng s\\u1edbm cho \\u0111\\u1ebfn 12h tr\\u01b0a.\",\"skill\":\"vocabulary\",\"difficulty\":\"A1\"},{\"question\":\"\\u0110\\u00fang hay Sai: C\\u00e2u \\\"They is from Vietnam.\\\" l\\u00e0 m\\u1ed9t c\\u00e2u \\u0111\\u00fang ng\\u1eef ph\\u00e1p ti\\u1ebfng Anh.\",\"question_type\":\"true_false\",\"options\":[\"True (\\u0110\\u00fang)\",\"False (Sai)\"],\"answer\":1,\"correct_answer\":\"False (Sai)\",\"explanation\":\"Sai. Ch\\u1ee7 ng\\u1eef \\\"They\\\" l\\u00e0 \\u0111\\u1ea1i t\\u1eeb s\\u1ed1 nhi\\u1ec1u n\\u00ean ph\\u1ea3i \\u0111i v\\u1edbi \\u0111\\u1ed9ng t\\u1eeb TO BE l\\u00e0 \\\"are\\\" (They are from Vietnam).\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"N\\u1ed1i \\u0111\\u1ea1i t\\u1eeb nh\\u00e2n x\\u01b0ng \\u1edf c\\u1ed9t b\\u00ean tr\\u00e1i v\\u1edbi d\\u1ea1ng \\u0111\\u1ed9ng t\\u1eeb TO BE t\\u01b0\\u01a1ng \\u1ee9ng \\u1edf c\\u1ed9t b\\u00ean ph\\u1ea3i:\",\"question_type\":\"matching\",\"options\":{\"left\":{\"I\":\"I\",\"You\":\"You\",\"He\":\"He\"},\"right\":[\"am\",\"are\",\"is\"]},\"answer\":0,\"correct_answer\":\"{\\\"I\\\":\\\"am\\\",\\\"You\\\":\\\"are\\\",\\\"He\\\":\\\"is\\\"}\",\"explanation\":\"Quy t\\u1eafc chia TO BE: I am, You are, He is.\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"\\u0110i\\u1ec1n m\\u1ed9t t\\u1eeb th\\u00edch h\\u1ee3p v\\u00e0o ch\\u1ed7 tr\\u1ed1ng \\u0111\\u1ec3 ho\\u00e0n th\\u00e0nh c\\u00e2u ch\\u00e0o quen thu\\u1ed9c: \\\"Nice to _____ you!\\\"\",\"question_type\":\"fill_blank\",\"options\":[\"meet\"],\"answer\":0,\"correct_answer\":\"meet\",\"explanation\":\"C\\u1ee5m t\\u1eeb c\\u1ed1 \\u0111\\u1ecbnh trong ti\\u1ebfng Anh: \\\"Nice to meet you\\\" c\\u00f3 ngh\\u0129a l\\u00e0 \\\"R\\u1ea5t vui \\u0111\\u01b0\\u1ee3c g\\u1eb7p b\\u1ea1n\\\".\",\"skill\":\"vocabulary\",\"difficulty\":\"A1\"}]}', 5, 15, 1, 0, NULL, NULL, 'auto_grade', '80.00', 'highest', NULL, 10, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:28'),
(18, 2, '📖 Từ vựng: Các thành viên trong Gia đình (Family Members)', NULL, 'vocabulary', '[{\"word\":\"Parents\",\"phonetic\":\"\\/\\u02c8per\\u0259nts\\/\",\"meaning\":\"B\\u1ed1 m\\u1eb9 (ph\\u1ee5 huynh)\",\"example\":\"My parents live in Da Nang.\"},{\"word\":\"Father\",\"phonetic\":\"\\/\\u02c8f\\u0251\\u02d0\\u00f0\\u0259r\\/\",\"meaning\":\"B\\u1ed1, cha\",\"example\":\"My father is an engineer.\"},{\"word\":\"Mother\",\"phonetic\":\"\\/\\u02c8m\\u028c\\u00f0\\u0259r\\/\",\"meaning\":\"M\\u1eb9\",\"example\":\"My mother cooks very well.\"},{\"word\":\"Brother\",\"phonetic\":\"\\/\\u02c8br\\u028c\\u00f0\\u0259r\\/\",\"meaning\":\"Anh \\/ Em trai\",\"example\":\"I have an older brother.\"},{\"word\":\"Sister\",\"phonetic\":\"\\/\\u02c8s\\u026ast\\u0259r\\/\",\"meaning\":\"Ch\\u1ecb \\/ Em g\\u00e1i\",\"example\":\"My sister is a high school student.\"},{\"word\":\"Grandfather\",\"phonetic\":\"\\/\\u02c8\\u0261r\\u00e6nf\\u0251\\u02d0\\u00f0\\u0259r\\/\",\"meaning\":\"\\u00d4ng n\\u1ed9i \\/ \\u00d4ng ngo\\u1ea1i\",\"example\":\"My grandfather loves reading newspapers.\"},{\"word\":\"Grandmother\",\"phonetic\":\"\\/\\u02c8\\u0261r\\u00e6nm\\u028c\\u00f0\\u0259r\\/\",\"meaning\":\"B\\u00e0 n\\u1ed9i \\/ B\\u00e0 ngo\\u1ea1i\",\"example\":\"My grandmother is 75 years old.\"},{\"word\":\"Daughter\",\"phonetic\":\"\\/\\u02c8d\\u0254\\u02d0t\\u0259r\\/\",\"meaning\":\"Con g\\u00e1i\",\"example\":\"They have one son and one daughter.\"}]', 1, 10, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(19, 2, '📖 Từ vựng: Các ngành nghề phổ biến (Jobs & Occupations)', NULL, 'vocabulary', '[{\"word\":\"Teacher\",\"phonetic\":\"\\/\\u02c8ti\\u02d0t\\u0283\\u0259r\\/\",\"meaning\":\"Gi\\u00e1o vi\\u00ean\",\"example\":\"She is an elementary school teacher.\"},{\"word\":\"Doctor\",\"phonetic\":\"\\/\\u02c8d\\u0251\\u02d0kt\\u0259r\\/\",\"meaning\":\"B\\u00e1c s\\u0129\",\"example\":\"The doctor is examining the patient.\"},{\"word\":\"Nurse\",\"phonetic\":\"\\/n\\u025c\\u02d0rs\\/\",\"meaning\":\"Y t\\u00e1, \\u0111i\\u1ec1u d\\u01b0\\u1ee1ng\",\"example\":\"The nurse is very attentive and kind.\"},{\"word\":\"Engineer\",\"phonetic\":\"\\/\\u02ccend\\u0292\\u026a\\u02c8n\\u026ar\\/\",\"meaning\":\"K\\u1ef9 s\\u01b0\",\"example\":\"He works as a civil engineer.\"},{\"word\":\"Chef\",\"phonetic\":\"\\/\\u0283ef\\/\",\"meaning\":\"\\u0110\\u1ea7u b\\u1ebfp\",\"example\":\"The head chef prepares delicious Italian pasta.\"},{\"word\":\"Police officer\",\"phonetic\":\"\\/p\\u0259\\u02c8li\\u02d0s \\u02cc\\u0254\\u02d0f\\u026as\\u0259r\\/\",\"meaning\":\"C\\u1ea3nh s\\u00e1t, c\\u00f4ng an\",\"example\":\"My uncle is a police officer.\"}]', 2, 10, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(20, 2, '📐 Ngữ pháp: Tính từ sở hữu (my, your, his, her, their, our) & Sở hữu cách (\'s)', NULL, 'grammar', '{\"title\":\"Quy t\\u1eafc s\\u1eed d\\u1ee5ng T\\u00ednh t\\u1eeb s\\u1edf h\\u1eefu v\\u00e0 S\\u1edf h\\u1eefu c\\u00e1ch\",\"explanation\":\"T\\u00ednh t\\u1eeb s\\u1edf h\\u1eefu lu\\u00f4n \\u0111\\u1ee9ng tr\\u01b0\\u1edbc danh t\\u1eeb \\u0111\\u1ec3 ch\\u1ec9 s\\u1ef1 s\\u1edf h\\u1eefu ho\\u1eb7c m\\u1ed1i quan h\\u1ec7. S\\u1edf h\\u1eefu c\\u00e1ch (\'s) \\u0111\\u01b0\\u1ee3c d\\u00f9ng sau danh t\\u1eeb ch\\u1ec9 ng\\u01b0\\u1eddi.\",\"rules\":[\"I \\u2192 my (c\\u1ee7a t\\u00f4i) | You \\u2192 your (c\\u1ee7a b\\u1ea1n) | We \\u2192 our (c\\u1ee7a ch\\u00fang t\\u00f4i) | They \\u2192 their (c\\u1ee7a h\\u1ecd)\",\"He \\u2192 his (c\\u1ee7a anh \\u1ea5y) | She \\u2192 her (c\\u1ee7a c\\u00f4 \\u1ea5y) | It \\u2192 its (c\\u1ee7a n\\u00f3)\",\"S\\u1edf h\\u1eefu c\\u00e1ch: Danh t\\u1eeb s\\u1ed1 \\u00edt + \'s + Danh t\\u1eeb s\\u1edf h\\u1eefu \\u2192 Mary\'s cat (Con m\\u00e8o c\\u1ee7a Mary), My brother\'s car (Xe \\u00f4 t\\u00f4 c\\u1ee7a anh t\\u00f4i).\",\"L\\u01b0u \\u00fd: Kh\\u00f4ng d\\u00f9ng m\\u1ea1o t\\u1eeb (a, an, the) tr\\u01b0\\u1edbc t\\u00ednh t\\u1eeb s\\u1edf h\\u1eefu.\"],\"examples\":[\"This is my mother. Her name is Mai.\",\"Peter is an engineer. His company is in Ho Chi Minh City.\",\"What is your father\'s job? - He is a doctor.\",\"Our family has four members: my parents, my sister, and me.\"]}', 3, 15, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(21, 2, '🎯 Quiz CBT: Gia đình & Tính từ sở hữu', NULL, 'quiz', '{\"questions\":[{\"question\":\"Ch\\u1ecdn t\\u00ednh t\\u1eeb s\\u1edf h\\u1eefu th\\u00edch h\\u1ee3p \\u0111\\u1ec3 \\u0111i\\u1ec1n v\\u00e0o ch\\u1ed7 tr\\u1ed1ng: \\\"John loves reading. _____ favorite hobby is books.\\\"\",\"question_type\":\"mcq\",\"options\":[\"Her\",\"His\",\"My\",\"Their\"],\"answer\":1,\"correct_answer\":\"His\",\"explanation\":\"John l\\u00e0 nam (ng\\u00f4i th\\u1ee9 3 s\\u1ed1 \\u00edt gi\\u1ed1ng \\u0111\\u1ef1c) n\\u00ean t\\u00ednh t\\u1eeb s\\u1edf h\\u1eefu t\\u01b0\\u01a1ng \\u1ee9ng l\\u00e0 \\\"His\\\".\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"T\\u1eeb n\\u00e0o sau \\u0111\\u00e2y c\\u00f3 ngh\\u0129a l\\u00e0 \\\"B\\u1ed1 m\\u1eb9\\\" trong ti\\u1ebfng Anh?\",\"question_type\":\"mcq\",\"options\":[\"Grandparents\",\"Children\",\"Parents\",\"Cousins\"],\"answer\":2,\"correct_answer\":\"Parents\",\"explanation\":\"\\\"Parents\\\" l\\u00e0 danh t\\u1eeb s\\u1ed1 nhi\\u1ec1u ch\\u1ec9 c\\u1ea3 b\\u1ed1 v\\u00e0 m\\u1eb9.\",\"skill\":\"vocabulary\",\"difficulty\":\"A1\"},{\"question\":\"N\\u1ed1i ngh\\u1ec1 nghi\\u1ec7p b\\u1eb1ng ti\\u1ebfng Anh v\\u1edbi ngh\\u0129a ti\\u1ebfng Vi\\u1ec7t t\\u01b0\\u01a1ng \\u1ee9ng:\",\"question_type\":\"matching\",\"options\":{\"left\":{\"Teacher\":\"Teacher\",\"Doctor\":\"Doctor\",\"Chef\":\"Chef\"},\"right\":[\"Gi\\u00e1o vi\\u00ean\",\"B\\u00e1c s\\u0129\",\"\\u0110\\u1ea7u b\\u1ebfp\"]},\"answer\":0,\"correct_answer\":\"{\\\"Teacher\\\":\\\"Gi\\\\u00e1o vi\\\\u00ean\\\",\\\"Doctor\\\":\\\"B\\\\u00e1c s\\\\u0129\\\",\\\"Chef\\\":\\\"\\\\u0110\\\\u1ea7u b\\\\u1ebfp\\\"}\",\"explanation\":\"Teacher: Gi\\u00e1o vi\\u00ean, Doctor: B\\u00e1c s\\u0129, Chef: \\u0110\\u1ea7u b\\u1ebfp.\",\"skill\":\"vocabulary\",\"difficulty\":\"A1\"},{\"question\":\"\\u0110i\\u1ec1n t\\u1eeb s\\u1edf h\\u1eefu c\\u00e1ch ph\\u00f9 h\\u1ee3p: \\\"This is my _____ (brother) laptop.\\\"\",\"question_type\":\"fill_blank\",\"options\":[\"brother\'s\"],\"answer\":0,\"correct_answer\":\"brother\'s\",\"explanation\":\"Th\\u00eam \'s v\\u00e0o sau danh t\\u1eeb s\\u1ed1 \\u00edt \\\"brother\\\" \\u0111\\u1ec3 t\\u1ea1o s\\u1edf h\\u1eefu c\\u00e1ch: brother\'s.\",\"skill\":\"grammar\",\"difficulty\":\"A1\"}]}', 4, 15, 1, 0, NULL, NULL, 'auto_grade', '80.00', 'highest', NULL, 10, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(22, 3, '📖 Từ vựng: Số đếm, Ngày trong tuần & Các tháng trong năm', NULL, 'vocabulary', '[{\"word\":\"Monday\",\"phonetic\":\"\\/\\u02c8m\\u028cnde\\u026a\\/\",\"meaning\":\"Th\\u1ee9 Hai\",\"example\":\"I have an English class on Monday.\"},{\"word\":\"Friday\",\"phonetic\":\"\\/\\u02c8fra\\u026ade\\u026a\\/\",\"meaning\":\"Th\\u1ee9 S\\u00e1u\",\"example\":\"Friday is my favorite day of the week.\"},{\"word\":\"Weekend\",\"phonetic\":\"\\/\\u02c8wi\\u02d0kend\\/\",\"meaning\":\"Cu\\u1ed1i tu\\u1ea7n (Th\\u1ee9 B\\u1ea3y & Ch\\u1ee7 Nh\\u1eadt)\",\"example\":\"We usually relax on the weekend.\"},{\"word\":\"Morning\",\"phonetic\":\"\\/\\u02c8m\\u0254\\u02d0rn\\u026a\\u014b\\/\",\"meaning\":\"Bu\\u1ed5i s\\u00e1ng\",\"example\":\"I wake up early in the morning.\"},{\"word\":\"Noon\",\"phonetic\":\"\\/nu\\u02d0n\\/\",\"meaning\":\"Bu\\u1ed5i tr\\u01b0a (ch\\u00ednh x\\u00e1c 12h)\",\"example\":\"Let\'s have lunch together at noon.\"},{\"word\":\"Midnight\",\"phonetic\":\"\\/\\u02c8m\\u026adna\\u026at\\/\",\"meaning\":\"N\\u1eeda \\u0111\\u00eam (24h \\u0111\\u00eam)\",\"example\":\"He rarely stays up past midnight.\"},{\"word\":\"Clock\",\"phonetic\":\"\\/kl\\u0251\\u02d0k\\/\",\"meaning\":\"\\u0110\\u1ed3ng h\\u1ed3 treo t\\u01b0\\u1eddng \\/ \\u0111\\u1ec3 b\\u00e0n\",\"example\":\"The clock on the wall shows 3 PM.\"},{\"word\":\"O\'clock\",\"phonetic\":\"\\/\\u0259\\u02c8kl\\u0251\\u02d0k\\/\",\"meaning\":\"Gi\\u1edd \\u0111\\u00fang (ch\\u1eb5n gi\\u1edd)\",\"example\":\"The meeting begins at seven o\'clock.\"}]', 1, 10, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(23, 3, '🎬 Video: Cách hỏi và trả lời về giờ giấc trong tiếng Anh', NULL, 'video', '{\"video_url\":\"https:\\/\\/www.youtube.com\\/watch?v=fq2tRfHMFbI\",\"title\":\"Telling Time in English - Easy Rules & Examples\",\"description\":\"H\\u01b0\\u1edbng d\\u1eabn \\u0111\\u1ea7y \\u0111\\u1ee7 2 c\\u00e1ch \\u0111\\u1ecdc gi\\u1edd trong ti\\u1ebfng Anh: C\\u00e1ch \\u0111\\u1ecdc \\u0111\\u01a1n gi\\u1ea3n (Gi\\u1edd + Ph\\u00fat) v\\u00e0 c\\u00e1ch \\u0111\\u1ecdc truy\\u1ec1n th\\u1ed1ng s\\u1eed d\\u1ee5ng \\\"Past\\\" (h\\u01a1n) v\\u00e0 \\\"To\\\" (k\\u00e9m).\",\"duration\":\"07:15\"}', 2, 12, 1, 0, NULL, NULL, 'auto_view', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(24, 3, '📐 Ngữ pháp: Giới từ chỉ thời gian (In, On, At) thần tốc', NULL, 'grammar', '{\"title\":\"Quy t\\u1eafc tam gi\\u00e1c gi\\u1edbi t\\u1eeb ch\\u1ec9 th\\u1eddi gian: AT - ON - IN\",\"explanation\":\"H\\u00e3y ghi nh\\u1edb quy t\\u1eafc t\\u1eeb h\\u1eb9p \\u0111\\u1ebfn r\\u1ed9ng: AT (c\\u1ee5 th\\u1ec3 nh\\u1ea5t: gi\\u1edd gi\\u1ea5c, th\\u1eddi \\u0111i\\u1ec3m), ON (ng\\u00e0y, th\\u1ee9 trong tu\\u1ea7n), IN (kho\\u1ea3ng th\\u1eddi gian r\\u1ed9ng: th\\u00e1ng, n\\u0103m, m\\u00f9a, th\\u1ebf k\\u1ef7).\",\"rules\":[\"AT + Gi\\u1edd c\\u1ee5 th\\u1ec3 \\/ D\\u1ecbp l\\u1ec5 ng\\u1eafn: at 6:30 AM, at noon, at midnight, at Christmas.\",\"ON + Ng\\u00e0y c\\u1ee5 th\\u1ec3 \\/ Th\\u1ee9 trong tu\\u1ea7n \\/ Ng\\u00e0y l\\u1ec5 c\\u00f3 t\\u1eeb \\\"Day\\\": on Monday, on July 4th, on my birthday, on Christmas Day.\",\"IN + Th\\u00e1ng \\/ N\\u0103m \\/ M\\u00f9a \\/ C\\u00e1c bu\\u1ed5i trong ng\\u00e0y: in July, in 2026, in summer, in the morning, in the evening.\"],\"examples\":[\"The class starts at 8:00 AM sharp.\",\"We don\'t go to school on Sundays.\",\"Vietnam is very beautiful in the spring.\",\"He was born in 2002.\"]}', 3, 15, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(25, 3, '🏆 Đề thi Tổng kết Khóa học A1 (Comprehensive Final Exam)', NULL, 'quiz', '{\"questions\":[{\"question\":\"Ch\\u1ecdn gi\\u1edbi t\\u1eeb ch\\u00ednh x\\u00e1c \\u0111\\u1ec3 \\u0111i\\u1ec1n v\\u00e0o ch\\u1ed7 tr\\u1ed1ng: \\\"The concert takes place _____ 8:00 PM tonight.\\\"\",\"question_type\":\"mcq\",\"options\":[\"in\",\"on\",\"at\",\"to\"],\"answer\":2,\"correct_answer\":\"at\",\"explanation\":\"D\\u00f9ng gi\\u1edbi t\\u1eeb \\\"at\\\" tr\\u01b0\\u1edbc m\\u1ed1c gi\\u1edd c\\u1ee5 th\\u1ec3 trong ng\\u00e0y (at 8:00 PM).\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"Ch\\u1ecdn gi\\u1edbi t\\u1eeb ch\\u00ednh x\\u00e1c: \\\"My birthday is _____ October 15th.\\\"\",\"question_type\":\"mcq\",\"options\":[\"at\",\"on\",\"in\",\"by\"],\"answer\":1,\"correct_answer\":\"on\",\"explanation\":\"C\\u00f3 ng\\u00e0y c\\u1ee5 th\\u1ec3 trong th\\u00e1ng (October 15th) n\\u00ean ph\\u1ea3i d\\u00f9ng gi\\u1edbi t\\u1eeb \\\"on\\\".\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"\\u0110\\u00fang hay Sai: C\\u1ee5m t\\u1eeb \\\"in Monday\\\" l\\u00e0 c\\u00e1ch di\\u1ec5n \\u0111\\u1ea1t ch\\u00ednh x\\u00e1c trong ti\\u1ebfng Anh.\",\"question_type\":\"true_false\",\"options\":[\"True (\\u0110\\u00fang)\",\"False (Sai)\"],\"answer\":1,\"correct_answer\":\"False (Sai)\",\"explanation\":\"Sai. V\\u1edbi c\\u00e1c th\\u1ee9 trong tu\\u1ea7n ta ph\\u1ea3i d\\u00f9ng gi\\u1edbi t\\u1eeb \\\"on\\\" (on Monday).\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"N\\u1ed1i c\\u1ee5m th\\u1eddi gian \\u1edf c\\u1ed9t b\\u00ean tr\\u00e1i v\\u1edbi gi\\u1edbi t\\u1eeb ch\\u00ednh x\\u00e1c \\u1edf c\\u1ed9t b\\u00ean ph\\u1ea3i:\",\"question_type\":\"matching\",\"options\":{\"left\":{\"7:30 AM\":\"7:30 AM\",\"Sunday\":\"Sunday\",\"the morning\":\"the morning\"},\"right\":[\"at\",\"on\",\"in\"]},\"answer\":0,\"correct_answer\":\"{\\\"7:30 AM\\\":\\\"at\\\",\\\"Sunday\\\":\\\"on\\\",\\\"the morning\\\":\\\"in\\\"}\",\"explanation\":\"at 7:30 AM (gi\\u1edd c\\u1ee5 th\\u1ec3), on Sunday (th\\u1ee9 trong tu\\u1ea7n), in the morning (bu\\u1ed5i trong ng\\u00e0y).\",\"skill\":\"grammar\",\"difficulty\":\"A1\"},{\"question\":\"\\u0110i\\u1ec1n t\\u1eeb c\\u00f2n thi\\u1ebfu v\\u00e0o ch\\u1ed7 tr\\u1ed1ng: \\\"She always drinks coffee _____ the morning.\\\"\",\"question_type\":\"fill_blank\",\"options\":[\"in\"],\"answer\":0,\"correct_answer\":\"in\",\"explanation\":\"C\\u1ee5m t\\u1eeb ch\\u1ec9 bu\\u1ed5i trong ng\\u00e0y d\\u00f9ng gi\\u1edbi t\\u1eeb \\\"in\\\": in the morning.\",\"skill\":\"grammar\",\"difficulty\":\"A1\"}]}', 4, 20, 1, 0, NULL, NULL, 'auto_grade', '80.00', 'highest', NULL, 15, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(26, 4, '📖 Từ vựng: Sở thích & Các môn thể thao phổ biến', NULL, 'vocabulary', '[{\"word\":\"Photography\",\"phonetic\":\"\\/f\\u0259\\u02c8t\\u0251\\u02d0\\u0261r\\u0259fi\\/\",\"meaning\":\"Nhi\\u1ebfp \\u1ea3nh, ch\\u1ee5p \\u1ea3nh\",\"example\":\"His main hobby is landscape photography.\"},{\"word\":\"Swimming\",\"phonetic\":\"\\/\\u02c8sw\\u026am\\u026a\\u014b\\/\",\"meaning\":\"B\\u01a1i l\\u1ed9i\",\"example\":\"I go swimming twice a week to stay fit.\"},{\"word\":\"Playing guitar\",\"phonetic\":\"\\/\\u02c8ple\\u026a\\u026a\\u014b \\u0261\\u026a\\u02c8t\\u0251\\u02d0r\\/\",\"meaning\":\"Ch\\u01a1i \\u0111\\u00e0n ghi-ta\",\"example\":\"He loves playing acoustic guitar in the evening.\"},{\"word\":\"Hiking\",\"phonetic\":\"\\/\\u02c8ha\\u026ak\\u026a\\u014b\\/\",\"meaning\":\"\\u0110i b\\u1ed9 leo n\\u00fai\",\"example\":\"We are planning a hiking trip to Sapa.\"},{\"word\":\"Gardening\",\"phonetic\":\"\\/\\u02c8\\u0261\\u0251\\u02d0rdn\\u026a\\u014b\\/\",\"meaning\":\"L\\u00e0m v\\u01b0\\u1eddn, ch\\u0103m c\\u00e2y\",\"example\":\"My grandmother finds gardening very relaxing.\"},{\"word\":\"Traveling\",\"phonetic\":\"\\/\\u02c8tr\\u00e6v\\u0259l\\u026a\\u014b\\/\",\"meaning\":\"Du l\\u1ecbch, kh\\u00e1m ph\\u00e1\",\"example\":\"Traveling around the world is her dream.\"},{\"word\":\"Cookery\",\"phonetic\":\"\\/\\u02c8k\\u028ak\\u0259ri\\/\",\"meaning\":\"Ngh\\u1ec7 thu\\u1eadt n\\u1ea5u \\u0103n\",\"example\":\"She attends a weekend cookery workshop.\"},{\"word\":\"Board game\",\"phonetic\":\"\\/\\u02c8b\\u0254\\u02d0rd \\u0261e\\u026am\\/\",\"meaning\":\"Tr\\u00f2 ch\\u01a1i c\\u1edd b\\u00e0n (c\\u1edd vua, c\\u1edd t\\u1ec9 ph\\u00fa)\",\"example\":\"We enjoy playing board games with friends.\"}]', 1, 10, 1, 1, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(27, 4, '📐 Ngữ pháp: Thì Hiện tại đơn (Present Simple) & Trạng từ tần suất', NULL, 'grammar', '{\"title\":\"Th\\u00ec Hi\\u1ec7n t\\u1ea1i \\u0111\\u01a1n & V\\u1ecb tr\\u00ed c\\u1ee7a Tr\\u1ea1ng t\\u1eeb ch\\u1ec9 t\\u1ea7n su\\u1ea5t\",\"explanation\":\"Th\\u00ec Hi\\u1ec7n t\\u1ea1i \\u0111\\u01a1n d\\u00f9ng \\u0111\\u1ec3 di\\u1ec5n \\u0111\\u1ea1t th\\u00f3i quen h\\u00e0ng ng\\u00e0y, s\\u1edf th\\u00edch, s\\u1ef1 th\\u1eadt hi\\u1ec3n nhi\\u00ean ho\\u1eb7c th\\u1eddi gian bi\\u1ec3u c\\u1ed1 \\u0111\\u1ecbnh.\",\"rules\":[\"Kh\\u1eb3ng \\u0111\\u1ecbnh: S (I\\/You\\/We\\/They) + V(nguy\\u00ean th\\u1ec3) | S (He\\/She\\/It) + V(s\\/es). V\\u00ed d\\u1ee5: I play football. He plays tennis.\",\"Ph\\u1ee7 \\u0111\\u1ecbnh: S + do not \\/ does not (don\'t \\/ doesn\'t) + V(nguy\\u00ean th\\u1ec3). V\\u00ed d\\u1ee5: She doesn\'t like coffee.\",\"Nghi v\\u1ea5n: Do \\/ Does + S + V(nguy\\u00ean th\\u1ec3)? V\\u00ed d\\u1ee5: Do you live in Hanoi? \\u2192 Yes, I do.\",\"Tr\\u1ea1ng t\\u1eeb ch\\u1ec9 t\\u1ea7n su\\u1ea5t (always, usually, often, sometimes, rarely, never) \\u0111\\u1ee9ng TR\\u01af\\u1edaC \\u0111\\u1ed9ng t\\u1eeb th\\u01b0\\u1eddng v\\u00e0 \\u0111\\u1ee9ng SAU \\u0111\\u1ed9ng t\\u1eeb TO BE.\"],\"examples\":[\"I always read a book before going to sleep.\",\"He is never late for his English morning class.\",\"She often goes swimming with her brother on weekends.\",\"Water freezes at zero degrees Celsius.\"]}', 2, 15, 1, 1, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(28, 4, '🎧 Luyện nghe: Phỏng vấn sở thích cuối tuần (Weekend Free Time Interview)', NULL, 'audio_listening', '{\"audio_url\":\"https:\\/\\/www.soundhelix.com\\/examples\\/mp3\\/SoundHelix-Song-2.mp3\",\"title\":\"Interview with Emma about her Favorite Hobbies\",\"transcript\":\"Interviewer: Good morning Emma! Thank you for joining us today. What do you usually do in your free time?\\nEmma: Good morning! Well, I have quite a busy work schedule during the week, so on weekends, I always make time for my hobbies. My biggest passion is landscape photography.\\nInterviewer: That sounds exciting! Do you travel a lot for your photography?\\nEmma: Yes, I often go hiking in the mountains with my camera. Being close to nature helps me recharge. Occasionally, if the weather is rainy, I stay home and bake bread with my sister.\\nInterviewer: Sounds like a wonderful and balanced lifestyle!\"}', 3, 12, 1, 0, NULL, NULL, 'auto_view', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(29, 4, '🎯 Quiz CBT: Luyện tập Thì hiện tại đơn & Sở thích', NULL, 'quiz', '{\"questions\":[{\"question\":\"Chia \\u0111\\u1ed9ng t\\u1eeb trong ngo\\u1eb7c \\u1edf th\\u00ec Hi\\u1ec7n t\\u1ea1i \\u0111\\u01a1n: \\\"My brother _____ (play) guitar very well.\\\"\",\"question_type\":\"mcq\",\"options\":[\"play\",\"plays\",\"playing\",\"is play\"],\"answer\":1,\"correct_answer\":\"plays\",\"explanation\":\"Ch\\u1ee7 ng\\u1eef \\\"My brother\\\" l\\u00e0 ng\\u00f4i th\\u1ee9 3 s\\u1ed1 \\u00edt n\\u00ean \\u0111\\u1ed9ng t\\u1eeb \\\"play\\\" th\\u00eam \\\"s\\\" th\\u00e0nh \\\"plays\\\".\",\"skill\":\"grammar\",\"difficulty\":\"A2\"},{\"question\":\"X\\u00e1c \\u0111\\u1ecbnh v\\u1ecb tr\\u00ed ch\\u00ednh x\\u00e1c c\\u1ee7a tr\\u1ea1ng t\\u1eeb \\\"usually\\\" trong c\\u00e2u sau: \\\"He _____ late for work.\\\"\",\"question_type\":\"mcq\",\"options\":[\"is usually\",\"usually is\",\"is usually not\",\"usually are\"],\"answer\":0,\"correct_answer\":\"is usually\",\"explanation\":\"Quy t\\u1eafc: Tr\\u1ea1ng t\\u1eeb ch\\u1ec9 t\\u1ea7n su\\u1ea5t \\u0111\\u1ee9ng SAU \\u0111\\u1ed9ng t\\u1eeb TO BE (He is usually late).\",\"skill\":\"grammar\",\"difficulty\":\"A2\"},{\"question\":\"N\\u1ed1i t\\u1eeb ch\\u1ec9 s\\u1edf th\\u00edch ti\\u1ebfng Anh v\\u1edbi \\u0111\\u1ecbnh ngh\\u0129a t\\u01b0\\u01a1ng \\u1ee9ng:\",\"question_type\":\"matching\",\"options\":{\"left\":{\"Photography\":\"Photography\",\"Hiking\":\"Hiking\",\"Gardening\":\"Gardening\"},\"right\":[\"Ch\\u1ee5p \\u1ea3nh ngh\\u1ec7 thu\\u1eadt\",\"\\u0110i b\\u1ed9 leo n\\u00fai\",\"L\\u00e0m v\\u01b0\\u1eddn ch\\u0103m c\\u00e2y\"]},\"answer\":0,\"correct_answer\":\"{\\\"Photography\\\":\\\"Ch\\\\u1ee5p \\\\u1ea3nh ngh\\\\u1ec7 thu\\\\u1eadt\\\",\\\"Hiking\\\":\\\"\\\\u0110i b\\\\u1ed9 leo n\\\\u00fai\\\",\\\"Gardening\\\":\\\"L\\\\u00e0m v\\\\u01b0\\\\u1eddn ch\\\\u0103m c\\\\u00e2y\\\"}\",\"explanation\":\"Photography: Ch\\u1ee5p \\u1ea3nh; Hiking: Leo n\\u00fai; Gardening: L\\u00e0m v\\u01b0\\u1eddn.\",\"skill\":\"vocabulary\",\"difficulty\":\"A2\"},{\"question\":\"\\u0110i\\u1ec1n d\\u1ea1ng ph\\u1ee7 \\u0111\\u1ecbnh \\u0111\\u00fang c\\u1ee7a \\u0111\\u1ed9ng t\\u1eeb: \\\"They _____ (not \\/ like) eating fast food.\\\"\",\"question_type\":\"fill_blank\",\"options\":[\"don\'t like\",\"do not like\"],\"answer\":0,\"correct_answer\":\"don\'t like\",\"explanation\":\"Ch\\u1ee7 ng\\u1eef \\\"They\\\" d\\u00f9ng tr\\u1ee3 \\u0111\\u1ed9ng t\\u1eeb \\\"do not\\\" (don\'t) + \\u0111\\u1ed9ng t\\u1eeb nguy\\u00ean th\\u1ec3 like.\",\"skill\":\"grammar\",\"difficulty\":\"A2\"}]}', 4, 15, 1, 0, NULL, NULL, 'auto_grade', '80.00', 'highest', NULL, 10, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(30, 5, '📖 Từ vựng: Hiện tượng Thời tiết & Các mùa trong năm', NULL, 'vocabulary', '[{\"word\":\"Sunny\",\"phonetic\":\"\\/\\u02c8s\\u028cni\\/\",\"meaning\":\"C\\u00f3 n\\u1eafng, tr\\u1eddi n\\u1eafng\",\"example\":\"It is a bright and sunny morning.\"},{\"word\":\"Rainy\",\"phonetic\":\"\\/\\u02c8re\\u026ani\\/\",\"meaning\":\"C\\u00f3 m\\u01b0a, nhi\\u1ec1u m\\u01b0a\",\"example\":\"Take an umbrella, it is rainy outside.\"},{\"word\":\"Cloudy\",\"phonetic\":\"\\/\\u02c8kla\\u028adi\\/\",\"meaning\":\"Nhi\\u1ec1u m\\u00e2y, r\\u00e2m m\\u00e1t\",\"example\":\"The sky is cloudy, it might rain soon.\"},{\"word\":\"Windy\",\"phonetic\":\"\\/\\u02c8w\\u026andi\\/\",\"meaning\":\"Nhi\\u1ec1u gi\\u00f3\",\"example\":\"It is too windy to play badminton in the park.\"},{\"word\":\"Forecast\",\"phonetic\":\"\\/\\u02c8f\\u0254\\u02d0rk\\u00e6st\\/\",\"meaning\":\"B\\u1ea3n tin d\\u1ef1 b\\u00e1o (th\\u1eddi ti\\u1ebft)\",\"example\":\"According to the weather forecast, tomorrow will be hot.\"},{\"word\":\"Temperature\",\"phonetic\":\"\\/\\u02c8tempr\\u0259t\\u0283\\u0259r\\/\",\"meaning\":\"Nhi\\u1ec7t \\u0111\\u1ed9\",\"example\":\"The temperature today is around 28 degrees Celsius.\"},{\"word\":\"Spring\",\"phonetic\":\"\\/spr\\u026a\\u014b\\/\",\"meaning\":\"M\\u00f9a xu\\u00e2n\",\"example\":\"Flowers blossom beautifully in spring.\"},{\"word\":\"Autumn\",\"phonetic\":\"\\/\\u02c8\\u0254\\u02d0t\\u0259m\\/\",\"meaning\":\"M\\u00f9a thu\",\"example\":\"Leaves turn golden yellow in autumn.\"}]', 1, 10, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(31, 5, '🎬 Video: Cách nghe và hiểu bản tin Dự báo thời tiết tiếng Anh', NULL, 'video', '{\"video_url\":\"https:\\/\\/www.youtube.com\\/watch?v=D1Z_v7A_6zY\",\"title\":\"Talking About the Weather in English\",\"description\":\"H\\u1ecdc c\\u00e1c m\\u1eabu c\\u00e2u giao ti\\u1ebfp t\\u1ef1 nhi\\u00ean v\\u1ec1 th\\u1eddi ti\\u1ebft c\\u1ee7a ng\\u01b0\\u1eddi b\\u1ea3n x\\u1ee9: h\\u1ecfi th\\u0103m nhi\\u1ec7t \\u0111\\u1ed9, nh\\u1eadn x\\u00e9t v\\u1ec1 th\\u1eddi ti\\u1ebft v\\u00e0 th\\u1ea3o lu\\u1eadn trang ph\\u1ee5c ph\\u00f9 h\\u1ee3p.\",\"duration\":\"09:20\"}', 2, 12, 1, 0, NULL, NULL, 'auto_view', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(32, 5, '📐 Ngữ pháp: Thì Tương lai gần (Be going to) & Phân biệt với \"Will\"', NULL, 'grammar', '{\"title\":\"C\\u1ea5u tr\\u00fac \\\"Be going to\\\" di\\u1ec5n t\\u1ea3 K\\u1ebf ho\\u1ea1ch & D\\u1ef1 \\u0111o\\u00e1n c\\u00f3 c\\u0103n c\\u1ee9\",\"explanation\":\"\\\"Be going to\\\" d\\u00f9ng \\u0111\\u1ec3 n\\u00f3i v\\u1ec1 nh\\u1eefng k\\u1ebf ho\\u1ea1ch, d\\u1ef1 \\u0111\\u1ecbnh \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c chu\\u1ea9n b\\u1ecb tr\\u01b0\\u1edbc th\\u1eddi \\u0111i\\u1ec3m n\\u00f3i, ho\\u1eb7c d\\u1ef1 \\u0111o\\u00e1n \\u0111i\\u1ec1u ch\\u1eafc ch\\u1eafn x\\u1ea3y ra d\\u1ef1a tr\\u00ean d\\u1ea5u hi\\u1ec7u hi\\u1ec7n t\\u1ea1i.\",\"rules\":[\"C\\u00f4ng th\\u1ee9c: S + am\\/is\\/are + going to + V(nguy\\u00ean th\\u1ec3).\",\"D\\u1ef1 \\u0111\\u1ecbnh tr\\u01b0\\u1edbc: I am going to visit my grandparents this weekend.\",\"D\\u1ef1 \\u0111o\\u00e1n c\\u00f3 b\\u1eb1ng ch\\u1ee9ng: Look at those dark clouds! It is going to rain.\",\"Ph\\u00e2n bi\\u1ec7t v\\u1edbi \\\"Will\\\": \\\"Will\\\" d\\u00f9ng cho quy\\u1ebft \\u0111\\u1ecbnh t\\u1ee9c th\\u1eddi n\\u1ea3y ra t\\u1ea1i l\\u00fac n\\u00f3i, ho\\u1eb7c l\\u1eddi h\\u1ee9a\\/d\\u1ef1 \\u0111o\\u00e1n kh\\u00f4ng c\\u00f3 b\\u1eb1ng ch\\u1ee9ng r\\u00f5 r\\u00e0ng.\"],\"examples\":[\"We are going to buy a new car next month.\",\"Are you going to attend the seminar tomorrow?\",\"She is not going to travel this summer because of work.\",\"Watch out! You are going to drop that glass.\"]}', 3, 15, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(33, 5, '🎯 Quiz CBT: Thời tiết & Dự định tương lai', NULL, 'quiz', '{\"questions\":[{\"question\":\"Nh\\u00ecn nh\\u1eefng \\u0111\\u00e1m m\\u00e2y \\u0111en k\\u1ecbt tr\\u00ean b\\u1ea7u tr\\u1eddi: \\\"Look at those dark clouds! It _____ rain soon.\\\"\",\"question_type\":\"mcq\",\"options\":[\"is going to\",\"will\",\"is going\",\"shall\"],\"answer\":0,\"correct_answer\":\"is going to\",\"explanation\":\"C\\u00f3 b\\u1eb1ng ch\\u1ee9ng tr\\u1ef1c ti\\u1ebfp \\u1edf hi\\u1ec7n t\\u1ea1i (dark clouds) n\\u00ean d\\u00f9ng c\\u1ea5u tr\\u00fac d\\u1ef1 \\u0111o\\u00e1n \\\"is going to rain\\\".\",\"skill\":\"grammar\",\"difficulty\":\"A2\"},{\"question\":\"T\\u1eeb v\\u1ef1ng n\\u00e0o m\\u00f4 t\\u1ea3 th\\u1eddi ti\\u1ebft c\\u00f3 nhi\\u1ec1u gi\\u00f3 m\\u1ea1nh?\",\"question_type\":\"mcq\",\"options\":[\"Sunny\",\"Windy\",\"Foggy\",\"Rainy\"],\"answer\":1,\"correct_answer\":\"Windy\",\"explanation\":\"\\\"Windy\\\" xu\\u1ea5t ph\\u00e1t t\\u1eeb danh t\\u1eeb \\\"wind\\\" (gi\\u00f3), c\\u00f3 ngh\\u0129a l\\u00e0 tr\\u1eddi nhi\\u1ec1u gi\\u00f3.\",\"skill\":\"vocabulary\",\"difficulty\":\"A2\"},{\"question\":\"N\\u1ed1i t\\u1eeb ch\\u1ec9 m\\u00f9a trong n\\u0103m v\\u1edbi \\u0111\\u1eb7c tr\\u01b0ng kh\\u00ed h\\u1eadu:\",\"question_type\":\"matching\",\"options\":{\"left\":{\"Summer\":\"Summer\",\"Winter\":\"Winter\",\"Spring\":\"Spring\"},\"right\":[\"N\\u1eafng n\\u00f3ng gay g\\u1eaft\",\"L\\u1ea1nh gi\\u00e1 bu\\u1ed1t\",\"\\u1ea4m \\u00e1p hoa n\\u1edf\"]},\"answer\":0,\"correct_answer\":\"{\\\"Summer\\\":\\\"N\\\\u1eafng n\\\\u00f3ng gay g\\\\u1eaft\\\",\\\"Winter\\\":\\\"L\\\\u1ea1nh gi\\\\u00e1 bu\\\\u1ed1t\\\",\\\"Spring\\\":\\\"\\\\u1ea4m \\\\u00e1p hoa n\\\\u1edf\\\"}\",\"explanation\":\"Summer: N\\u00f3ng; Winter: L\\u1ea1nh; Spring: \\u1ea4m \\u00e1p.\",\"skill\":\"vocabulary\",\"difficulty\":\"A2\"},{\"question\":\"\\u0110i\\u1ec1n t\\u1eeb c\\u00f2n thi\\u1ebfu: \\\"They are _____ to visit Ha Long Bay next Sunday.\\\"\",\"question_type\":\"fill_blank\",\"options\":[\"going\"],\"answer\":0,\"correct_answer\":\"going\",\"explanation\":\"C\\u1ea5u tr\\u00fac d\\u1ef1 \\u0111\\u1ecbnh: are going to visit.\",\"skill\":\"grammar\",\"difficulty\":\"A2\"}]}', 4, 15, 1, 0, NULL, NULL, 'auto_grade', '80.00', 'highest', NULL, 10, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(34, 6, '📖 Từ vựng: Đi siêu thị, Giá cả & Dịch vụ nhà hàng', NULL, 'vocabulary', '[{\"word\":\"Discount\",\"phonetic\":\"\\/\\u02c8d\\u026aska\\u028ant\\/\",\"meaning\":\"Chi\\u1ebft kh\\u1ea5u, gi\\u1ea3m gi\\u00e1\",\"example\":\"Is there any student discount available?\"},{\"word\":\"Receipt\",\"phonetic\":\"\\/r\\u026a\\u02c8si\\u02d0t\\/\",\"meaning\":\"H\\u00f3a \\u0111\\u01a1n thanh to\\u00e1n\",\"example\":\"Please keep your receipt for returns.\"},{\"word\":\"Cash\",\"phonetic\":\"\\/k\\u00e6\\u0283\\/\",\"meaning\":\"Ti\\u1ec1n m\\u1eb7t\",\"example\":\"Would you like to pay by card or in cash?\"},{\"word\":\"Customer\",\"phonetic\":\"\\/\\u02c8k\\u028cst\\u0259m\\u0259r\\/\",\"meaning\":\"Kh\\u00e1ch h\\u00e0ng\",\"example\":\"The shop staff is always polite to customers.\"},{\"word\":\"Menu\",\"phonetic\":\"\\/\\u02c8menju\\u02d0\\/\",\"meaning\":\"Th\\u1ef1c \\u0111\\u01a1n m\\u00f3n \\u0103n\",\"example\":\"Could we please see the dessert menu?\"},{\"word\":\"Delicious\",\"phonetic\":\"\\/d\\u026a\\u02c8l\\u026a\\u0283\\u0259s\\/\",\"meaning\":\"Ngon mi\\u1ec7ng, th\\u01a1m ngon\",\"example\":\"This grilled salmon is absolutely delicious.\"},{\"word\":\"Affordable\",\"phonetic\":\"\\/\\u0259\\u02c8f\\u0254\\u02d0rd\\u0259bl\\/\",\"meaning\":\"Gi\\u00e1 c\\u1ea3 ph\\u1ea3i ch\\u0103ng, h\\u1ee3p t\\u00fai ti\\u1ec1n\",\"example\":\"The restaurant offers high quality food at affordable prices.\"},{\"word\":\"Order\",\"phonetic\":\"\\/\\u02c8\\u0254\\u02d0rd\\u0259r\\/\",\"meaning\":\"G\\u1ecdi m\\u00f3n, \\u0111\\u1eb7t h\\u00e0ng\",\"example\":\"Are you ready to order your main course?\"}]', 1, 10, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(35, 6, '📐 Ngữ pháp: Danh từ Đếm được / Không đếm được & How Much / How Many', NULL, 'grammar', '{\"title\":\"Ph\\u00e2n bi\\u1ec7t Danh t\\u1eeb \\u0110\\u1ebfm \\u0111\\u01b0\\u1ee3c & Kh\\u00f4ng \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c v\\u00e0 C\\u00e2u h\\u1ecfi s\\u1ed1 l\\u01b0\\u1ee3ng \\/ gi\\u00e1 c\\u1ea3\",\"explanation\":\"Danh t\\u1eeb \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c c\\u00f3 th\\u1ec3 \\u0111\\u1ebfm b\\u1eb1ng s\\u1ed1 (1 qu\\u1ea3 t\\u00e1o, 2 qu\\u1ea3 t\\u00e1o). Danh t\\u1eeb kh\\u00f4ng \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c l\\u00e0 ch\\u1ea5t l\\u1ecfng, h\\u1ea1t nh\\u1ecf, kh\\u00e1i ni\\u1ec7m tr\\u1eebu t\\u01b0\\u1ee3ng (n\\u01b0\\u1edbc, ti\\u1ec1n, \\u0111\\u01b0\\u1eddng, th\\u00f4ng tin).\",\"rules\":[\"HOW MANY + Danh t\\u1eeb \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c s\\u1ed1 nhi\\u1ec1u: How many apples do you want? (H\\u1ecfi v\\u1ec1 s\\u1ed1 l\\u01b0\\u1ee3ng)\",\"HOW MUCH + Danh t\\u1eeb kh\\u00f4ng \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c: How much water do you drink every day? (H\\u1ecfi v\\u1ec1 l\\u01b0\\u1ee3ng)\",\"HOW MUCH + \\u0110\\u1ed9ng t\\u1eeb TO BE \\/ COST: How much is this shirt? \\/ How much does it cost? (H\\u1ecfi v\\u1ec1 gi\\u00e1 ti\\u1ec1n)\",\"M\\u1ed9t s\\u1ed1 danh t\\u1eeb kh\\u00f4ng \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c \\u0111i\\u1ec3n h\\u00ecnh: money, water, milk, coffee, information, rice, bread, furniture.\"],\"examples\":[\"How much is that cup of cappuccino? - It is 45,000 VND.\",\"How many cups of coffee do you drink a day? - Two cups.\",\"How much money do you need for shopping?\",\"There are many people at the supermarket today.\"]}', 2, 15, 1, 0, NULL, NULL, 'manual', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(36, 6, '🎧 Luyện nghe: Gọi món tại Nhà hàng (Ordering at an Italian Restaurant)', NULL, 'audio_listening', '{\"audio_url\":\"https:\\/\\/www.soundhelix.com\\/examples\\/mp3\\/SoundHelix-Song-3.mp3\",\"title\":\"Ordering Dinner at Luigi\'s Bistro\",\"transcript\":\"Waiter: Good evening! Welcome to Luigi\'s Bistro. Do you have a table reserved?\\nCustomer: Yes, a table for two under the name of Thomas, please.\\nWaiter: Ah yes, right this way sir! Here are your menus. Would you like to start with some drinks?\\nCustomer: Just sparkling water for now, thank you.\\nWaiter: Are you ready to order or would you like a few more minutes?\\nCustomer: We\'re ready! Could we please have one Seafood Pasta and one Margherita Pizza?\\nWaiter: Excellent choice. And would you like any salad or appetizers to share?\\nCustomer: Yes, a Caesar salad would be wonderful, thank you!\"}', 3, 12, 1, 0, NULL, NULL, 'auto_view', NULL, 'highest', NULL, NULL, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05'),
(37, 6, '🏆 Đề thi Đánh giá Năng lực Cuối khóa A2 (Comprehensive Final Exam)', NULL, 'quiz', '{\"questions\":[{\"question\":\"Ch\\u1ecdn c\\u1ee5m t\\u1eeb ch\\u00ednh x\\u00e1c \\u0111\\u1ec3 h\\u1ecfi gi\\u00e1 c\\u1ee7a chi\\u1ebfc \\u00e1o kho\\u00e1c: \\\"_____ is this winter jacket?\\\"\",\"question_type\":\"mcq\",\"options\":[\"How many\",\"How much\",\"How long\",\"How often\"],\"answer\":1,\"correct_answer\":\"How much\",\"explanation\":\"D\\u00f9ng \\\"How much\\\" \\u0111\\u1ec3 h\\u1ecfi gi\\u00e1 ti\\u1ec1n c\\u1ee7a m\\u1ed9t m\\u00f3n \\u0111\\u1ed3.\",\"skill\":\"grammar\",\"difficulty\":\"A2\"},{\"question\":\"Ch\\u1ecdn t\\u1eeb th\\u00edch h\\u1ee3p \\u0111\\u1ec3 \\u0111i\\u1ec1n v\\u00e0o c\\u00e2u h\\u1ecfi s\\u1ed1 l\\u01b0\\u1ee3ng: \\\"How _____ students are there in your class?\\\"\",\"question_type\":\"mcq\",\"options\":[\"much\",\"many\",\"more\",\"lot\"],\"answer\":1,\"correct_answer\":\"many\",\"explanation\":\"\\\"Students\\\" l\\u00e0 danh t\\u1eeb \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c s\\u1ed1 nhi\\u1ec1u n\\u00ean d\\u00f9ng \\\"How many\\\".\",\"skill\":\"grammar\",\"difficulty\":\"A2\"},{\"question\":\"T\\u1eeb n\\u00e0o sau \\u0111\\u00e2y l\\u00e0 Danh t\\u1eeb KH\\u00d4NG \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c (Uncountable Noun)?\",\"question_type\":\"mcq\",\"options\":[\"Table\",\"Apple\",\"Water\",\"Student\"],\"answer\":2,\"correct_answer\":\"Water\",\"explanation\":\"\\\"Water\\\" (n\\u01b0\\u1edbc) l\\u00e0 ch\\u1ea5t l\\u1ecfng, danh t\\u1eeb kh\\u00f4ng \\u0111\\u1ebfm \\u0111\\u01b0\\u1ee3c.\",\"skill\":\"vocabulary\",\"difficulty\":\"A2\"},{\"question\":\"N\\u1ed1i t\\u1eeb v\\u1ef1ng mua s\\u1eafm v\\u1edbi \\u00fd ngh\\u0129a t\\u01b0\\u01a1ng \\u1ee9ng:\",\"question_type\":\"matching\",\"options\":{\"left\":{\"Receipt\":\"Receipt\",\"Discount\":\"Discount\",\"Customer\":\"Customer\"},\"right\":[\"H\\u00f3a \\u0111\\u01a1n thanh to\\u00e1n\",\"M\\u1ee9c chi\\u1ebft kh\\u1ea5u gi\\u1ea3m gi\\u00e1\",\"Kh\\u00e1ch h\\u00e0ng mua s\\u1eafm\"]},\"answer\":0,\"correct_answer\":\"{\\\"Receipt\\\":\\\"H\\\\u00f3a \\\\u0111\\\\u01a1n thanh to\\\\u00e1n\\\",\\\"Discount\\\":\\\"M\\\\u1ee9c chi\\\\u1ebft kh\\\\u1ea5u gi\\\\u1ea3m gi\\\\u00e1\\\",\\\"Customer\\\":\\\"Kh\\\\u00e1ch h\\\\u00e0ng mua s\\\\u1eafm\\\"}\",\"explanation\":\"Receipt: H\\u00f3a \\u0111\\u01a1n; Discount: Gi\\u1ea3m gi\\u00e1; Customer: Kh\\u00e1ch h\\u00e0ng.\",\"skill\":\"vocabulary\",\"difficulty\":\"A2\"},{\"question\":\"\\u0110i\\u1ec1n t\\u1eeb c\\u00f2n thi\\u1ebfu v\\u00e0o m\\u1eabu c\\u00e2u h\\u1ecfi gi\\u00e1 ti\\u1ec1n: \\\"How much _____ this book cost?\\\"\",\"question_type\":\"fill_blank\",\"options\":[\"does\"],\"answer\":0,\"correct_answer\":\"does\",\"explanation\":\"Ch\\u1ee7 ng\\u1eef \\\"this book\\\" l\\u00e0 s\\u1ed1 \\u00edt, \\u0111\\u1ed9ng t\\u1eeb th\\u01b0\\u1eddng \\\"cost\\\" n\\u00ean tr\\u1ee3 \\u0111\\u1ed9ng t\\u1eeb l\\u00e0 \\\"does\\\".\",\"skill\":\"grammar\",\"difficulty\":\"A2\"}]}', 4, 20, 1, 0, NULL, NULL, 'auto_grade', '80.00', 'highest', NULL, 15, NULL, '2026-09-07 02:07:05', '2026-09-07 02:07:05');

