--
-- Table structure for table `adaptive_test_sessions`
--

CREATE TABLE `adaptive_test_sessions` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `current_difficulty` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A1',
  `consecutive_correct` int(11) NOT NULL DEFAULT 0,
  `consecutive_wrong` int(11) NOT NULL DEFAULT 0,
  `question_history` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`question_history`)),
  `answers_history` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`answers_history`)),
  `total_questions_answered` int(11) NOT NULL DEFAULT 0,
  `correct_count` int(11) NOT NULL DEFAULT 0,
  `score` int(11) NOT NULL DEFAULT 0,
  `status` enum('active','finished') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `final_level` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

