(1, 1, 'A1', 0, 1, '[10]', '[{\"question_id\":10,\"question_text\":\"[Giao ti\\u1ebfp] Khi ai \\u0111\\u00f3 n\\u00f3i \\\"Thank you very much!\\\", b\\u1ea1n s\\u1ebd \\u0111\\u00e1p l\\u1ea1i nh\\u01b0 th\\u1ebf n\\u00e0o?\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"question_type\":\"mcq\",\"options\":[\"Goodbye!\",\"You\'re welcome!\",\"See you later.\",\"I am sorry.\"],\"user_answer\":\"See you later.\",\"correct_answer\":\"You\'re welcome!\",\"is_correct\":false,\"explanation\":\"\\\"You\'re welcome!\\\" (Kh\\u00f4ng c\\u00f3 g\\u00ec \\u0111\\u00e2u!) l\\u00e0 c\\u00e2u \\u0111\\u00e1p l\\u1ea1i ph\\u1ed5 bi\\u1ebfn v\\u00e0 l\\u1ecbch s\\u1ef1 nh\\u1ea5t khi \\u0111\\u01b0\\u1ee3c c\\u1ea3m \\u01a1n.\",\"feedback_note\":null,\"passage\":null,\"passage_title\":null,\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\",\"min_words\":null,\"task_type\":null,\"testlet_index\":null,\"testlet_badge\":null,\"testlet_info\":null,\"testlet_question_num\":null,\"testlet_size\":null}]', 1, 0, 0, 'finished', NULL, '2026-09-07 08:34:03', '2026-09-07 08:37:36'),
