CEFR level.\\\"\"}}', '2026-09-07 03:51:20', '2026-09-07 03:51:20'),
(3, 1, NULL, 'adaptive_test', 1, 0, 'completed', NULL, NULL, 150, 400, 37.5, 0, '[{\"question_id\":9,\"question_text\":\"[\\u00c2m thanh] Ng\\u01b0\\u1eddi n\\u00f3i h\\u1ecfi: \\\"What time is it?\\\" - C\\u00e2u tr\\u1ea3 l\\u1eddi ph\\u00f9 h\\u1ee3p nh\\u1ea5t l\\u00e0:\",\"question_type\":\"mcq\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"I am fine, thank you.\",\"correct_answer\":\"It is 8 o\'clock.\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"What time is it?\\\" d\\u00f9ng \\u0111\\u1ec3 h\\u1ecfi gi\\u1edd, c\\u00e2u tr\\u1ea3 l\\u1eddi l\\u00e0 \\\"It is 8 o\'clock\\\" (B\\u00e2y gi\\u1edd l\\u00e0 8 gi\\u1edd).\"},{\"question_id\":10,\"question_text\":\"[Giao ti\\u1ebfp] Khi ai \\u0111\\u00f3 n\\u00f3i \\\"Thank you very much!\\\", b\\u1ea1n s\\u1ebd \\u0111\\u00e1p l\\u1ea1i nh\\u01b0 th\\u1ebf n\\u00e0o?\",\"question_type\":\"mcq\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"Goodbye!\",\"correct_answer\":\"You\'re welcome!\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"You\'re welcome!\\\" (Kh\\u00f4ng c\\u00f3 g\\u00ec \\u0111\\u00e2u!) l\\u00e0 c\\u00e2u \\u0111\\u00e1p l\\u1ea1i ph\\u1ed5 bi\\u1ebfn v\\u00e0 l\\u1ecbch s\\u1ef1 nh\\u1ea5t khi \\u0111\\u01b0\\u1ee3c c\\u1ea3m \\u01a1n.\"},{\"question_id\":20,\"question_text\":\"[\\u0110\\u1eb7t ph\\u00f2ng] \\\"I would like to book a double room for two nights.\\\" Kh\\u00e1ch mu\\u1ed1n \\u0111\\u1eb7t ph\\u00f2ng cho m\\u1ea5y \\u0111\\u00eam?\",\"question_type\":\"mcq\",\"skill\":\"listening\",\"difficulty\":\"A2\",\"user_answer\":\"1 \\u0111\\u00eam\",\"correct_answer\":\"2 \\u0111\\u00eam\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"for two nights\\\" ngh\\u0129a l\\u00e0 \\u0111\\u1eb7t ph\\u00f2ng trong 2 \\u0111\\u00eam.\"},{\"question_id\":27,\"question_text\":\"\\u0110\\u1ecdc c\\u00e2u: \\\"Despite the heavy rain, the soccer match continued without interruption.\\\" \\u00dd ch\\u00ednh c\\u1ee7a c\\u00e2u l\\u00e0 g\\u00ec?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"B1\",\"user_answer\":\"A\",\"correct_answer\":\"Tr\\u1eadn \\u0111\\u1ea5u v\\u1eabn ti\\u1ebfp t\\u1ee5c d\\u00f9 tr\\u1eddi m\\u01b0a to\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"Despite the heavy rain... continued without interruption\\\" = M\\u1eb7c cho m\\u01b0a l\\u1edbn, tr\\u1eadn \\u0111\\u1ea5u v\\u1eabn di\\u1ec5n ra li\\u00ean t\\u1ee5c.\"},{\"question_id\":37,\"question_text\":\"Luy\\u1ec7n ph\\u00e1t \\u00e2m chu\\u1ea9n c\\u00e2u giao ti\\u1ebfp sau b\\u1eb1ng micro:\\n\\n\\\"Good morning, nice to meet you\\\"\",\"question_type\":\"pronunciation_speech\",\"skill\":\"speaking\",\"difficulty\":\"A1\",\"user_answer\":\"audio_recording_simulated_30s\",\"correct_answer\":\"Good morning, nice to meet you\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"Ph\\u00e1t \\u00e2m chu\\u1ea9n \\/\\u0261\\u028ad \\u02c8m\\u0254\\u02d0rn\\u026a\\u014b na\\u026as tu\\u02d0 mi\\u02d0t ju\\u02d0\\/.\"},{\"question_id\":38,\"question_text\":\"[\\u00c2m thanh] Ng\\u01b0\\u1eddi n\\u00f3i h\\u1ecfi: \\\"Where are you from?\\\" - C\\u00e2u tr\\u1ea3 l\\u1eddi ch\\u00ednh x\\u00e1c l\\u00e0:\",\"question_type\":\"mcq\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"I am from Vietnam.\",\"correct_answer\":\"I am from Vietnam.\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"\\\"Where are you from?\\\" h\\u1ecfi v\\u1ec1 qu\\u00ea qu\\u00e1n \\/ xu\\u1ea5t x\\u1ee9, c\\u00e2u tr\\u1ea3 l\\u1eddi l\\u00e0 \\\"I am from Vietnam\\\".\"},{\"question_id\":39,\"question_text\":\"[\\u00c2m thanh] Nghe \\u0111o\\u1ea1n h\\u1ed9i tho\\u1ea1i: \\\"How do you spell your name?\\\" - \\\"It\'s J-O-H-N.\\\" T\\u00ean ng\\u01b0\\u1eddi n\\u00f3i l\\u00e0 g\\u00ec?\",\"question_type\":\"mcq\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"John\",\"correct_answer\":\"John\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"\\u0110o\\u1ea1n \\u0111\\u00e1nh v\\u1ea7n r\\u00f5 r\\u00e0ng J-O-H-N l\\u00e0 John.\"},{\"question_id\":40,\"question_text\":\"Nghe th\\u00f4ng b\\u00e1o t\\u1ea1i nh\\u00e0 ga xe l\\u1eeda: \\\"The train to Oxford will depart from Platform 3 in five minutes.\\\" T\\u00e0u \\u0111i Oxford kh\\u1edfi h\\u00e0nh t\\u1ea1i s\\u00e2n ga n\\u00e0o?\",\"question_type\":\"listening_comprehension\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"Platform 1\",\"correct_answer\":\"Platform 3\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"Th\\u00f4ng b\\u00e1o n\\u00eau r\\u00f5: \\\"depart from Platform 3\\\" (kh\\u1edfi h\\u00e0nh t\\u1ea1i s\\u00e2n ga s\\u1ed1 3).\"},{\"question_id\":41,\"question_text\":\"Nghe c\\u00e2u h\\u1ecfi t\\u1ea1i qu\\u1ea7y l\\u1ec5 t\\u00e2n: \\\"May I have your room key, please?\\\" Ng\\u01b0\\u1eddi n\\u00f3i \\u0111ang y\\u00eau c\\u1ea7u \\u0111i\\u1ec1u g\\u00ec?\",\"question_type\":\"listening_comprehension\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"H\\u1ed9 chi\\u1ebfu\",\"correct_answer\":\"Ch\\u00eca kh\\u00f3a ph\\u00f2ng\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"Room key\\\" c\\u00f3 ngh\\u0129a l\\u00e0 ch\\u00eca kh\\u00f3a ph\\u00f2ng kh\\u00e1ch s\\u1ea1n.\"},{\"question_id\":42,\"question_text\":\"Nghe \\u0111o\\u1ea1n h\\u1ed9i tho\\u1ea1i mua s\\u1eafm: \\\"How much is this blue shirt?\\\" - \\\"It is twenty-five dollars.\\\" Chi\\u1ebfc \\u00e1o s\\u01a1 mi c\\u00f3 gi\\u00e1 bao nhi\\u00eau?\",\"question_type\":\"listening_comprehension\",\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"$15\",\"correct_answer\":\"$25\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"Ng\\u01b0\\u1eddi b\\u00e1n tr\\u1ea3 l\\u1eddi: \\\"twenty-five dollars\\\" ($25).\"},{\"question_id\":43,\"question_text\":\"Nghe tin nh\\u1eafn tho\\u1ea1i: \\\"Hi Tom, our meeting tomorrow has been moved from 9:00 AM to 10:30 AM in Room 204.\\\" Cu\\u1ed9c h\\u1ecdp d\\u1eddi sang m\\u1ea5y gi\\u1edd?\",\"question_type\":\"listening_comprehension\",\"skill\":\"listening\",\"difficulty\":\"A2\",\"user_answer\":\"9:00 AM\",\"correct_answer\":\"10:30 AM\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"L\\u1eddi nh\\u1eafn: \\\"moved from 9:00 AM to 10:30 AM\\\" (d\\u1eddi sang 10 gi\\u1edd 30 s\\u00e1ng).\"},{\"question_id\":45,\"question_text\":\"Nghe th\\u00f4ng b\\u00e1o th\\u1eddi ti\\u1ebft: \\\"Expect heavy rain this afternoon with temperatures dropping to 18 degrees Celsius. Don\'t forget your umbrella.\\\" Ng\\u01b0\\u1eddi nghe \\u0111\\u01b0\\u1ee3c khuy\\u00ean n\\u00ean mang theo g\\u00ec?\",\"question_type\":\"listening_comprehension\",\"skill\":\"listening\",\"difficulty\":\"A2\",\"user_answer\":\"K\\u00ednh r\\u00e2m\",\"correct_answer\":\"\\u00d4 \\/ d\\u00f9\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"Don\'t forget your umbrella\\\" ngh\\u0129a l\\u00e0 \\u0111\\u1eebng qu\\u00ean mang \\u00f4\\/d\\u00f9 che m\\u01b0a.\"},{\"question_id\":46,\"question_text\":\"Nghe \\u0111o\\u1ea1n trao \\u0111\\u1ed5i c\\u00f4ng vi\\u1ec7c: \\\"Due to the unexpected budget cuts, the marketing department will postpone the promotional campaign until next quarter.\\\" K\\u1ebf ho\\u1ea1ch ti\\u1ebfp th\\u1ecb b\\u1ecb \\u1ea3nh h\\u01b0\\u1edfng nh\\u01b0 th\\u1ebf n\\u00e0o?\",\"question_type\":\"listening_comprehension\",\"skill\":\"listening\",\"difficulty\":\"B1\",\"user_answer\":\"B\\u1ecb h\\u1ee7y b\\u1ecf v\\u0129nh vi\\u1ec5n\",\"correct_answer\":\"Ho\\u00e3n l\\u1ea1i sang qu\\u00fd t\\u1edbi\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"postpone the promotional campaign until next quarter\\\" c\\u00f3 ngh\\u0129a l\\u00e0 ho\\u00e3n chi\\u1ebfn d\\u1ecbch qu\\u1ea3ng b\\u00e1 \\u0111\\u1ebfn qu\\u00fd sau.\"},{\"question_id\":47,\"question_text\":\"Nghe th\\u00f4ng b\\u00e1o s\\u00e2n bay: \\\"Passengers on flight VN384 to Seoul please proceed to Gate 18 immediately for final boarding.\\\" H\\u00e0nh kh\\u00e1ch c\\u1ea7n l\\u00e0m g\\u00ec?\",\"question_type\":\"listening_comprehension\",\"skill\":\"listening\",\"difficulty\":\"B1\",\"user_answer\":\"L\\u1ea5y h\\u00e0nh l\\u00fd k\\u00fd g\\u1eedi\",\"correct_answer\":\"\\u0110\\u1ebfn C\\u1ed5ng 18 ngay l\\u1eadp t\\u1ee9c \\u0111\\u1ec3 l\\u00ean m\\u00e1y bay\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"proceed to Gate 18 immediately for final boarding\\\" c\\u00f3 ngh\\u0129a l\\u00e0 kh\\u1ea9n tr\\u01b0\\u01a1ng \\u0111\\u1ebfn C\\u1ed5ng 18 \\u0111\\u1ec3 l\\u00ean m\\u00e1y bay.\"},{\"question_id\":49,\"question_text\":\"\\u0110\\u1ecdc bi\\u1ec3n b\\u00e1o t\\u1ea1i th\\u01b0 vi\\u1ec7n: \\\"SILENCE PLEASE - Study Area\\\". Bi\\u1ec3n b\\u00e1o n\\u00e0y y\\u00eau c\\u1ea7u \\u0111i\\u1ec1u g\\u00ec?\",\"question_type\":\"reading_comprehension\",\"skill\":\"reading\",\"difficulty\":\"A1\",\"user_answer\":\"Kh\\u00f4ng \\u0111\\u01b0\\u1ee3c \\u0103n u\\u1ed1ng\",\"correct_answer\":\"Gi\\u1eef y\\u00ean l\\u1eb7ng\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"Silence please\\\" ngh\\u0129a l\\u00e0 xin vui l\\u00f2ng gi\\u1eef tr\\u1eadt t\\u1ef1\\/im l\\u1eb7ng.\"},{\"question_id\":50,\"question_text\":\"\\u0110\\u1ecdc th\\u00f4ng b\\u00e1o c\\u1eeda h\\u00e0ng: \\\"OPEN Monday - Saturday: 8:00 AM - 9:00 PM. CLOSED on Sundays.\\\" C\\u1eeda h\\u00e0ng \\u0111\\u00f3ng c\\u1eeda v\\u00e0o ng\\u00e0y n\\u00e0o?\",\"question_type\":\"reading_comprehension\",\"skill\":\"reading\",\"difficulty\":\"A1\",\"user_answer\":\"Th\\u1ee9 Hai\",\"correct_answer\":\"Ch\\u1ee7 Nh\\u1eadt\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"CLOSED on Sundays\\\" ngh\\u0129a l\\u00e0 \\u0111\\u00f3ng c\\u1eeda v\\u00e0o c\\u00e1c ng\\u00e0y Ch\\u1ee7 nh\\u1eadt.\"},{\"question_id\":51,\"question_text\":\"\\u0110\\u1ecdc email n\\u1ed9i b\\u1ed9: \\\"Dear Staff, our annual company picnic is scheduled for Saturday, October 15th at Green Lake Park. Transportation will be provided from the office at 7:30 AM.\\\" Xe \\u0111\\u01b0a \\u0111\\u00f3n nh\\u00e2n vi\\u00ean kh\\u1edfi h\\u00e0nh l\\u00fac m\\u1ea5y gi\\u1edd?\",\"question_type\":\"reading_comprehension\",\"skill\":\"reading\",\"difficulty\":\"A2\",\"user_answer\":\"6:30 AM\",\"correct_answer\":\"7:30 AM\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\u0110o\\u1ea1n v\\u0103n n\\u00eau r\\u00f5: \\\"Transportation will be provided from the office at 7:30 AM\\\".\"},{\"question_id\":52,\"question_text\":\"\\u0110\\u1ecdc t\\u1edd r\\u01a1i kh\\u00f3a h\\u1ecdc: \\\"English for Travel: Learn essential phrases for airports, hotels, and restaurants. 4 weeks, 2 sessions per week. Special 20% discount for early bird registration before May 1st.\\\" \\u01afu \\u0111\\u00e3i n\\u00e0o \\u0111\\u01b0\\u1ee3c d\\u00e0nh cho ng\\u01b0\\u1eddi \\u0111\\u0103ng k\\u00fd s\\u1edbm tr\\u01b0\\u1edbc ng\\u00e0y 1 th\\u00e1ng 5?\",\"question_type\":\"reading_comprehension\",\"skill\":\"reading\",\"difficulty\":\"A2\",\"user_answer\":\"T\\u1eb7ng s\\u00e1ch gi\\u00e1o tr\\u00ecnh mi\\u1ec5n ph\\u00ed\",\"correct_answer\":\"Gi\\u1ea3m 20% h\\u1ecdc ph\\u00ed\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"T\\u1edd r\\u01a1i ghi: \\\"Special 20% discount for early bird registration before May 1st\\\".\"},{\"question_id\":53,\"question_text\":\"Theo \\u0111o\\u1ea1n v\\u0103n, xu h\\u01b0\\u1edbng l\\u00e0m vi\\u1ec7c t\\u1eeb xa (remote work) mang l\\u1ea1i l\\u1ee3i \\u00edch m\\u00f4i tr\\u01b0\\u1eddng n\\u1ed5i b\\u1eadt n\\u00e0o?\",\"question_type\":\"reading_comprehension\",\"skill\":\"reading\",\"difficulty\":\"B1\",\"user_answer\":\"T\\u0103ng s\\u1ea3n l\\u01b0\\u1ee3ng ti\\u00eau th\\u1ee5 \\u0111i\\u1ec7n\",\"correct_answer\":\"Gi\\u1ea3m thi\\u1ec3u kh\\u00ed th\\u1ea3i c\\u00e1c-bon do gi\\u1ea3m ph\\u01b0\\u01a1ng ti\\u1ec7n \\u0111i l\\u1ea1i h\\u00e0ng ng\\u00e0y\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"B\\u00e0i vi\\u1ebft nh\\u1ea5n m\\u1ea1nh: \\\"reducing daily commutes has led to a measurable decline in carbon emissions and urban traffic congestion\\\".\"},{\"question_id\":54,\"question_text\":\"Theo \\u0111o\\u1ea1n v\\u0103n, nguy\\u00ean nh\\u00e2n ch\\u00ednh khi\\u1ebfn lo\\u00e0i ong m\\u1eadt suy gi\\u1ea3m qu\\u1ea7n th\\u1ec3 l\\u00e0 g\\u00ec?\",\"question_type\":\"reading_comprehension\",\"skill\":\"reading\",\"difficulty\":\"B1\",\"user_answer\":\"Thi\\u1ebfu ngu\\u1ed3n n\\u01b0\\u1edbc s\\u1ea1ch\",\"correct_answer\":\"S\\u1ef1 k\\u1ebft h\\u1ee3p gi\\u1eefa m\\u1ea5t m\\u00f4i tr\\u01b0\\u1eddng s\\u1ed1ng, thu\\u1ed1c tr\\u1eeb s\\u00e2u v\\u00e0 bi\\u1ebfn \\u0111\\u1ed5i kh\\u00ed h\\u1eadu\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"B\\u00e0i vi\\u1ebft n\\u00eau: \\\"a combination of habitat fragmentation, widespread pesticide use, and shifting climatic patterns\\\".\"},{\"question_id\":55,\"question_text\":\"H\\u00e3y vi\\u1ebft 2-3 c\\u00e2u \\u0111\\u01a1n gi\\u1ea3n (t\\u1ed1i thi\\u1ec3u 20 t\\u1eeb) gi\\u1edbi thi\\u1ec7u v\\u1ec1 m\\u1ed9t ng\\u01b0\\u1eddi b\\u1ea1n th\\u00e2n c\\u1ee7a b\\u1ea1n (t\\u00ean, tu\\u1ed5i, s\\u1edf th\\u00edch chung).\",\"question_type\":\"essay_writing\",\"skill\":\"writing\",\"difficulty\":\"A1\",\"user_answer\":\"A well structured analytical response with comprehensive ideas and fluent grammar meeting all word requirements.\",\"correct_answer\":\"My best friend is Nam. He is twenty years old. We love playing football and listening to music together on weekends.\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"Y\\u00eau c\\u1ea7u: gi\\u1edbi thi\\u1ec7u t\\u00ean, tu\\u1ed5i v\\u00e0 s\\u1edf th\\u00edch chung, s\\u1eed d\\u1ee5ng th\\u00ec hi\\u1ec7n t\\u1ea1i \\u0111\\u01a1n ch\\u00ednh x\\u00e1c.\"},{\"question_id\":56,\"question_text\":\"H\\u00e3y vi\\u1ebft m\\u1ed9t ghi ch\\u00fa ng\\u1eafn (t\\u1ed1i thi\\u1ec3u 20 t\\u1eeb) nh\\u1eafn ng\\u01b0\\u1eddi b\\u1ea1n c\\u00f9ng ph\\u00f2ng mua gi\\u00fap b\\u1ea1n m\\u1ed9t s\\u1ed1 \\u0111\\u1ed3 d\\u00f9ng (b\\u00e1nh m\\u00ec, s\\u1eefa, tr\\u1ee9ng).\",\"question_type\":\"essay_writing\",\"skill\":\"writing\",\"difficulty\":\"A1\",\"user_answer\":\"A well structured analytical response with comprehensive ideas and fluent grammar meeting all word requirements.\",\"correct_answer\":\"Hi John, I am studying at the library right now. Can you please buy some bread, milk, and eggs on your way home? Thanks a lot!\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"Vi\\u1ebft m\\u1ea9u tin nh\\u1eafn ng\\u1eafn g\\u1ecdn, n\\u00eau r\\u00f5 c\\u00e1c m\\u00f3n \\u0111\\u1ed3 c\\u1ea7n nh\\u1edd mua v\\u00e0 l\\u1eddi c\\u1ea3m \\u01a1n.\"},{\"question_id\":57,\"question_text\":\"B\\u1ea1n v\\u1eeba c\\u00f3 m\\u1ed9t chuy\\u1ebfn \\u0111i du l\\u1ecbch cu\\u1ed1i tu\\u1ea7n. H\\u00e3y vi\\u1ebft m\\u1ed9t email ng\\u1eafn (t\\u1ed1i thi\\u1ec3u 35 t\\u1eeb) k\\u1ec3 cho b\\u1ea1n b\\u00e8 nghe b\\u1ea1n \\u0111\\u00e3 \\u0111i \\u0111\\u00e2u, th\\u1eddi ti\\u1ebft nh\\u01b0 th\\u1ebf n\\u00e0o v\\u00e0 ho\\u1ea1t \\u0111\\u1ed9ng b\\u1ea1n th\\u00edch nh\\u1ea5t.\",\"question_type\":\"essay_writing\",\"skill\":\"writing\",\"difficulty\":\"A2\",\"user_answer\":\"A well structured analytical response with comprehensive ideas and fluent grammar meeting all word requirements.\",\"correct_answer\":\"Hi Sarah, last weekend I went to Da Nang with my family. The weather was very sunny and breezy. We swam at the beach and ate fresh seafood. I took a lot of photos that I will show you soon!\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"S\\u1eed d\\u1ee5ng th\\u00ec qu\\u00e1 kh\\u1ee9 \\u0111\\u01a1n (went, was, swam, took), c\\u1ea5u tr\\u00fac m\\u1ea1ch l\\u1ea1c v\\u00e0 \\u0111\\u1ee7 th\\u00f4ng tin.\"},{\"question_id\":58,\"question_text\":\"H\\u00e3y vi\\u1ebft m\\u1ed9t email xin ph\\u00e9p v\\u1eafng m\\u1eb7t (t\\u1ed1i thi\\u1ec3u 35 t\\u1eeb) g\\u1eedi cho gi\\u00e1o vi\\u00ean ti\\u1ebfng Anh gi\\u1ea3i th\\u00edch l\\u00fd do b\\u1ea1n kh\\u00f4ng th\\u1ec3 tham gia bu\\u1ed5i h\\u1ecdc v\\u00e0o ng\\u00e0y mai.\",\"question_type\":\"essay_writing\",\"skill\":\"writing\",\"difficulty\":\"A2\",\"user_answer\":\"A well structured analytical response with comprehensive ideas and fluent grammar meeting all word requirements.\",\"correct_answer\":\"Dear Teacher Mary, I am writing to inform you that I cannot attend our English class tomorrow because I have a doctor appointment. I will ask my classmate for the homework notes and submit my assignment on time.\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"Gi\\u1ecdng v\\u0103n l\\u1ecbch s\\u1ef1, n\\u00eau r\\u00f5 l\\u00fd do v\\u1eafng m\\u1eb7t v\\u00e0 cam k\\u1ebft ho\\u00e0n th\\u00e0nh b\\u00e0i t\\u1eadp v\\u1ec1 nh\\u00e0.\"},{\"question_id\":59,\"question_text\":\"Vi\\u1ebft m\\u1ed9t email ph\\u1ea3n h\\u1ed3i kh\\u00e1ch h\\u00e0ng (t\\u1ed1i thi\\u1ec3u 50 t\\u1eeb) xin l\\u1ed7i v\\u00ec \\u0111\\u01a1n h\\u00e0ng b\\u1ecb giao tr\\u1ec5 2 ng\\u00e0y v\\u00e0 \\u0111\\u01b0a ra ph\\u01b0\\u01a1ng \\u00e1n b\\u1ed3i th\\u01b0\\u1eddng (mi\\u1ec5n ph\\u00ed v\\u1eadn chuy\\u1ec3n ho\\u1eb7c gi\\u1ea3m gi\\u00e1 15% cho \\u0111\\u01a1n sau).\",\"question_type\":\"essay_writing\",\"skill\":\"writing\",\"difficulty\":\"B1\",\"user_answer\":\"A well structured analytical response with comprehensive ideas and fluent grammar meeting all word requirements.\",\"correct_answer\":\"Dear Mr. Miller, Thank you for contacting our customer support team. We sincerely apologize for the unexpected delay in delivering your package. To compensate for this inconvenience, we have refunded your shipping fee and credited a 15% discount voucher to your account for your next purchase.\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"Email th\\u01b0 t\\u00edn th\\u01b0\\u01a1ng m\\u1ea1i chuy\\u00ean nghi\\u1ec7p: nh\\u1eadn l\\u1ed7i ch\\u00e2n th\\u00e0nh, gi\\u1ea3i th\\u00edch nguy\\u00ean nh\\u00e2n v\\u00e0 \\u0111\\u01b0a ra gi\\u1ea3i ph\\u00e1p b\\u1ed3i ho\\u00e0n c\\u1ee5 th\\u1ec3.\"},{\"question_id\":63,\"question_text\":\"\\u0110\\u1ecdc to c\\u00e2u ch\\u00e0o h\\u1ecfi v\\u00e0 gi\\u1edbi thi\\u1ec7u b\\u1ea3n th\\u00e2n v\\u00e0o micro: \\\"Hello! My name is Alex. I come from Vietnam and I am happy to learn English.\\\"\",\"question_type\":\"audio_recording\",\"skill\":\"speaking\",\"difficulty\":\"A1\",\"user_answer\":\"audio_recording_simulated_30s\",\"correct_answer\":\"Ph\\u00e1t \\u00e2m chu\\u1ea9n ng\\u1eef \\u0111i\\u1ec7u c\\u00e2u \\u0111\\u01a1n gi\\u1ea3n, r\\u00f5 \\u00e2m \\u0111u\\u00f4i \\/s\\/ trong Alex, \\/m\\/ trong Vietnam.\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Ti\\u00eau ch\\u00ed: ph\\u00e1t \\u00e2m to r\\u00f5, kh\\u00f4ng ng\\u1eafc ng\\u1ee9, tr\\u1ecdng \\u00e2m chu\\u1ea9n.\"},{\"question_id\":66,\"question_text\":\"T\\u00ecnh hu\\u1ed1ng t\\u1ea1i nh\\u00e0 h\\u00e0ng: Ghi \\u00e2m cu\\u1ed9c g\\u1ecdi \\u0111\\u1eb7t b\\u00e0n (n\\u00f3i trong 20-30 gi\\u00e2y): \\u0110\\u1eb7t m\\u1ed9t b\\u00e0n cho 4 ng\\u01b0\\u1eddi v\\u00e0o t\\u1ed1i th\\u1ee9 S\\u00e1u l\\u00fac 7 gi\\u1edd t\\u1ed1i.\",\"question_type\":\"audio_recording\",\"skill\":\"speaking\",\"difficulty\":\"A2\",\"user_answer\":\"audio_recording_simulated_30s\",\"correct_answer\":\"Good morning! I would like to reserve a table for four people this Friday evening at 7:00 PM, please. Could we have a table by the window?\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Ti\\u00eau ch\\u00ed: gi\\u1ecdng \\u0111i\\u1ec7u l\\u1ecbch s\\u1ef1 (would like to reserve), \\u0111\\u1ea7y \\u0111\\u1ee7 s\\u1ed1 ng\\u01b0\\u1eddi, ng\\u00e0y gi\\u1edd v\\u00e0 y\\u00eau c\\u1ea7u th\\u00eam.\"},{\"question_id\":68,\"question_text\":\"X\\u1eed l\\u00fd t\\u00ecnh hu\\u1ed1ng c\\u00f4ng s\\u1edf: B\\u1ea1n tr\\u1ec5 h\\u1ea1n n\\u1ed9p b\\u00e1o c\\u00e1o cho s\\u1ebfp. H\\u00e3y ghi \\u00e2m l\\u1eddi gi\\u1ea3i th\\u00edch v\\u00e0 cam k\\u1ebft th\\u1eddi gian n\\u1ed9p b\\u00f9 (n\\u00f3i trong 30-40 gi\\u00e2y).\",\"question_type\":\"audio_recording\",\"skill\":\"speaking\",\"difficulty\":\"B1\",\"user_answer\":\"audio_recording_simulated_30s\",\"correct_answer\":\"Hi Ms. Jennifer, I sincerely apologize for the delay in submitting the quarterly sales report. We encountered unexpected data errors yesterday, but I am currently finalizing the corrections and will email the completed document by 3:00 PM today.\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Ti\\u00eau ch\\u00ed: xin l\\u1ed7i chuy\\u00ean nghi\\u1ec7p, gi\\u1ea3i th\\u00edch ng\\u1eafn g\\u1ecdn nguy\\u00ean nh\\u00e2n v\\u00e0 ch\\u1ed1t th\\u1eddi h\\u1ea1n n\\u1ed9p ch\\u00ednh x\\u00e1c.\"},{\"question_id\":69,\"question_text\":\"Thuy\\u1ebft tr\\u00ecnh ch\\u1ee7 \\u0111\\u1ec1 (n\\u00f3i trong 45-60 gi\\u00e2y): \\\"Do you think artificial intelligence will completely replace teachers in future classrooms? Explain your perspective.\\\"\",\"question_type\":\"audio_recording\",\"skill\":\"speaking\",\"difficulty\":\"B2\",\"user_answer\":\"audio_recording_simulated_30s\",\"correct_answer\":\"In my view, while artificial intelligence can undoubtedly personalize learning paths and automate administrative grading, it will never entirely supplant human educators. Teachers cultivate empathy, moral values, and critical thinking\\u2014qualities that algorithms cannot replicate.\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Ti\\u00eau ch\\u00ed: l\\u1eadp lu\\u1eadn ph\\u1ea3n bi\\u1ec7n s\\u1eafc s\\u1ea3o, s\\u1eed d\\u1ee5ng li\\u00ean t\\u1eeb ch\\u1ec9 s\\u1ef1 t\\u01b0\\u01a1ng ph\\u1ea3n (while, undoubtedly, never entirely supplant) v\\u00e0 ph\\u00e1t \\u00e2m l\\u01b0u lo\\u00e1t.\"},{\"question_id\":71,\"question_text\":\"TASK 1: Postcard to a Friend (At least 40 words)\\n\\nYou are on vacation at the beach. Write a short message to your friend Alex.\\nIn your message, you should:\\n- Tell Alex where you are\\n- Describe the weather\\n- Say what activities you did today\",\"question_type\":\"essay_writing\",\"skill\":\"writing\",\"difficulty\":\"A1\",\"user_answer\":\"A well structured analytical response with comprehensive ideas and fluent grammar meeting all word requirements.\",\"correct_answer\":\"A completed postcard meeting all 3 bullet points with at least 40 words.\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\u0110\\u1ea3m b\\u1ea3o vi\\u1ebft \\u0111\\u1ee7 3 \\u00fd: \\u0111\\u1ecba \\u0111i\\u1ec3m k\\u1ef3 ngh\\u1ec9, th\\u1eddi ti\\u1ebft v\\u00e0 c\\u00e1c ho\\u1ea1t \\u0111\\u1ed9ng \\u0111\\u00e3 l\\u00e0m.\"},{\"question_id\":73,\"question_text\":\"TASK 1: Formal Request Letter (At least 120 words)\\n\\nYou are planning a study tour for your class to a local science museum. Write a letter to the museum manager:\\n- Introduce yourself and your class\\n- Inquire about ticket discounts for groups\\n- Ask about guided tour schedules and special exhibitions\",\"question_type\":\"essay_writing\",\"skill\":\"writing\",\"difficulty\":\"B1\",\"user_answer\":\"A well structured analytical response with comprehensive ideas and fluent grammar meeting all word requirements.\",\"correct_answer\":\"A formal inquiry letter with proper opening, 3 clear bullet points, and professional closing.\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"S\\u1eed d\\u1ee5ng v\\u0103n phong trang tr\\u1ecdng (formal tone), di\\u1ec5n \\u0111\\u1ea1t r\\u00f5 r\\u00e0ng c\\u00e1c y\\u00eau c\\u1ea7u h\\u1ecfi th\\u00f4ng tin.\"},{\"question_id\":77,\"question_text\":\"PART 1: Shopping and Favorite Food (2 - 3 Minutes)\\n\\nPlease talk about your shopping habits and eating preferences:\\n1. Do you prefer shopping online or in traditional stores? Why?\\n2. What is your favorite dish and how often do you eat it?\\n3. Do you enjoy cooking at home or eating out with friends?\",\"question_type\":\"audio_recording\",\"skill\":\"speaking\",\"difficulty\":\"A2\",\"user_answer\":\"audio_recording_simulated_30s\",\"correct_answer\":\"audio_recording\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"S\\u1eed d\\u1ee5ng c\\u00e1c li\\u00ean t\\u1eeb n\\u1ed1i \\u0111\\u01a1n gi\\u1ea3n (because, and, but, so) \\u0111\\u1ec3 ph\\u00e1t tri\\u1ec3n c\\u00e2u tr\\u1ea3 l\\u1eddi.\"},{\"question_id\":78,\"question_text\":\"PART 2: Solution Discussion - Weekend Class Activity (3 - 4 Minutes)\\n\\nSituation: Your English class is planning an outdoor bonding activity for next Sunday. Three options are proposed:\\n- Option 1: A picnic in the city central park\\n- Option 2: A volunteer trip to an animal shelter\\n- Option 3: A museum visit followed by a coffee workshop\\n\\nWhich option do you think is best for the class? Explain your choice and state why you rejected the other two options.\",\"question_type\":\"audio_recording\",\"skill\":\"speaking\",\"difficulty\":\"B1\",\"user_answer\":\"audio_recording_simulated_30s\",\"correct_answer\":\"audio_recording\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"C\\u1ea5u tr\\u00fac b\\u00e0i n\\u00f3i: Ch\\u1ecdn 1 ph\\u01b0\\u01a1ng \\u00e1n t\\u1ed1i \\u01b0u, \\u0111\\u01b0a ra 2 l\\u00fd do \\u1ee7ng h\\u1ed9 v\\u00e0 n\\u00eau l\\u00fd do t\\u1eeb ch\\u1ed1i 2 ph\\u01b0\\u01a1ng \\u00e1n c\\u00f2n l\\u1ea1i.\"},{\"question_id\":81,\"question_text\":\"What is the primary objective of deploying IoT sensors in smart urban transit systems?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"B2\",\"user_answer\":\"To optimize real-time traffic flow and diminish transit congestion\",\"correct_answer\":\"To optimize real-time traffic flow and diminish transit congestion\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"The passage notes that IoT sensors monitor congestion dynamically to optimize signal timings and reduce transit gridlock.\"},{\"question_id\":85,\"question_text\":\"Where were wild coffee plants originally discovered according to historical accounts?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"B1\",\"user_answer\":\"The Ethiopian highlands\",\"correct_answer\":\"The Ethiopian highlands\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Legend and botanical history trace the origin of Coffea arabica to the ancient forests of the Ethiopian plateau.\"},{\"question_id\":89,\"question_text\":\"What makes hydrothermal vent ecosystems fundamentally distinct from terrestrial biomes?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"C1\",\"user_answer\":\"They derive primary metabolic energy from chemosynthesis rather than solar photosynthesis\",\"correct_answer\":\"They derive primary metabolic energy from chemosynthesis rather than solar photosynthesis\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Hydrothermal communities thrive on mineral-rich fluids metabolized by chemosynthetic bacteria rather than sunlight.\"},{\"question_id\":92,\"question_text\":\"What was the historical perception of the deep bathypelagic zone prior to modern exploration?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"C1\",\"user_answer\":\"It was presumed to be a barren and virtually lifeless expanse\",\"correct_answer\":\"It was presumed to be a barren and virtually lifeless expanse\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"The text states the abyss was \\\\\\\"once deemed a sterile wasteland\\\\\\\" before discovery of its biodiversity.\"},{\"question_id\":93,\"question_text\":\"\\u0110\\u1ecdc b\\u1ea3ng ch\\u1ec9 d\\u1eabn t\\u1ea1i s\\u00e2n bay: \\\\\\\"BAGGAGE CLAIM - Carousels 1 to 4 downstairs\\\\\\\". H\\u00e0nh kh\\u00e1ch c\\u1ea7n \\u0111i \\u0111\\u00e2u \\u0111\\u1ec3 l\\u1ea5y h\\u00e0nh l\\u00fd?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"A1\",\"user_answer\":\"\\u0110i xu\\u1ed1ng t\\u1ea7ng d\\u01b0\\u1edbi\",\"correct_answer\":\"\\u0110i xu\\u1ed1ng t\\u1ea7ng d\\u01b0\\u1edbi\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"\\\\\\\"Downstairs\\\\\\\" c\\u00f3 ngh\\u0129a l\\u00e0 \\u0111i xu\\u1ed1ng t\\u1ea7ng d\\u01b0\\u1edbi.\"},{\"question_id\":94,\"question_text\":\"\\u0110\\u1ecdc th\\u00f4ng b\\u00e1o ti\\u1ec7m gi\\u1eb7t \\u1ee7i: \\\\\\\"Express Service: Clothes dropped off before 10:00 AM will be ready by 5:00 PM on the same day.\\\\\\\" Mu\\u1ed1n l\\u1ea5y \\u0111\\u1ed3 gi\\u1eb7t trong ng\\u00e0y, kh\\u00e1ch c\\u1ea7n g\\u1eedi tr\\u01b0\\u1edbc m\\u1ea5y gi\\u1edd?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"A2\",\"user_answer\":\"Tr\\u01b0\\u1edbc 10:00 AM\",\"correct_answer\":\"Tr\\u01b0\\u1edbc 10:00 AM\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Th\\u00f4ng b\\u00e1o n\\u00eau: \\\\\\\"dropped off before 10:00 AM will be ready by 5:00 PM on the same day\\\\\\\".\"},{\"question_id\":95,\"question_text\":\"\\u0110\\u1ecdc email m\\u1eddi ph\\u1ecfng v\\u1ea5n: \\\\\\\"Please confirm your availability for an online interview via Zoom on Thursday at 2:00 PM.\\\\\\\" \\u1ee8ng vi\\u00ean \\u0111\\u01b0\\u1ee3c h\\u1eb9n ph\\u1ecfng v\\u1ea5n v\\u00e0o l\\u00fac n\\u00e0o v\\u00e0 qua h\\u00ecnh th\\u1ee9c n\\u00e0o?\",\"question_type\":\"mcq\",\"skill\":\"reading\",\"difficulty\":\"A2\",\"user_answer\":\"Th\\u1ee9 N\\u0103m l\\u00fac 2:00 PM qua Zoom\",\"correct_answer\":\"Th\\u1ee9 N\\u0103m l\\u00fac 2:00 PM qua Zoom\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"Th\\u01b0 ghi r\\u00f5: \\\\\\\"online interview via Zoom on Thursday at 2:00 PM\\\\\\\".\"}]', '2026-09-07 09:11:10', '2026-09-07 09:11:10'),
(4, 1, NULL, 'mock_test_a1', 1, 45, 'completed', '2026-09-07 17:02:05', '2026-09-08 00:02:54', 30, 80, 37.5, 0, '[{\"question_id\":9,\"version\":1,\"question_text\":\"[\\u00c2m thanh] Ng\\u01b0\\u1eddi n\\u00f3i h\\u1ecfi: \\\"What time is it?\\\" - C\\u00e2u tr\\u1ea3 l\\u1eddi ph\\u00f9 h\\u1ee3p nh\\u1ea5t l\\u00e0:\",\"question_type\":\"mcq\",\"options\":[\"I am fine, thank you.\",\"It is 8 o\'clock.\",\"My name is John.\",\"Yes, I do.\"],\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"It is 8 o\'clock.\",\"correct_answer\":\"It is 8 o\'clock.\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"\\\"What time is it?\\\" d\\u00f9ng \\u0111\\u1ec3 h\\u1ecfi gi\\u1edd, c\\u00e2u tr\\u1ea3 l\\u1eddi l\\u00e0 \\\"It is 8 o\'clock\\\" (B\\u00e2y gi\\u1edd l\\u00e0 8 gi\\u1edd).\"},{\"question_id\":10,\"version\":1,\"question_text\":\"[Giao ti\\u1ebfp] Khi ai \\u0111\\u00f3 n\\u00f3i \\\"Thank you very much!\\\", b\\u1ea1n s\\u1ebd \\u0111\\u00e1p l\\u1ea1i nh\\u01b0 th\\u1ebf n\\u00e0o?\",\"question_type\":\"mcq\",\"options\":[\"Goodbye!\",\"You\'re welcome!\",\"See you later.\",\"I am sorry.\"],\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"You\'re welcome!\",\"correct_answer\":\"You\'re welcome!\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"\\\"You\'re welcome!\\\" (Kh\\u00f4ng c\\u00f3 g\\u00ec \\u0111\\u00e2u!) l\\u00e0 c\\u00e2u \\u0111\\u00e1p l\\u1ea1i ph\\u1ed5 bi\\u1ebfn v\\u00e0 l\\u1ecbch s\\u1ef1 nh\\u1ea5t khi \\u0111\\u01b0\\u1ee3c c\\u1ea3m \\u01a1n.\"},{\"question_id\":38,\"version\":1,\"question_text\":\"[\\u00c2m thanh] Ng\\u01b0\\u1eddi n\\u00f3i h\\u1ecfi: \\\"Where are you from?\\\" - C\\u00e2u tr\\u1ea3 l\\u1eddi ch\\u00ednh x\\u00e1c l\\u00e0:\",\"question_type\":\"mcq\",\"options\":[\"I am from Vietnam.\",\"I am 20 years old.\",\"I like coffee.\",\"I am a student.\"],\"skill\":\"listening\",\"difficulty\":\"A1\",\"user_answer\":\"I am from Vietnam.\",\"correct_answer\":\"I am from Vietnam.\",\"is_correct\":true,\"is_answered\":true,\"explanation\":\"\\\"Where are you from?\\\" h\\u1ecfi v\\u1ec1 qu\\u00ea qu\\u00e1n \\/ xu\\u1ea5t x\\u1ee9, c\\u00e2u tr\\u1ea3 l\\u1eddi l\\u00e0 \\\"I am from Vietnam\\\".\"},{\"question_id\":7,\"version\":1,\"question_text\":\"\\u0110\\u1ecdc c\\u00e2u sau: \\\"Tom has a blue backpack and two pens.\\\" Tom c\\u00f3 c\\u00e1i g\\u00ec m\\u00e0u xanh n\\u01b0\\u1edbc bi\\u1ec3n?\",\"question_type\":\"mcq\",\"options\":[\"Hai chi\\u1ebfc b\\u00fat\",\"M\\u1ed9t chi\\u1ebfc ba l\\u00f4\",\"M\\u1ed9t quy\\u1ec3n s\\u00e1ch\",\"M\\u1ed9t \\u0111\\u00f4i gi\\u00e0y\"],\"skill\":\"reading\",\"difficulty\":\"A1\",\"user_answer\":\"Hai chi\\u1ebfc b\\u00fat\",\"correct_answer\":\"M\\u1ed9t chi\\u1ebfc ba l\\u00f4\",\"is_correct\":false,\"is_answered\":true,\"explanation\":\"\\\"Blue backpack\\\" c\\u00f3 ngh\\u0129a l\\u00e0 chi\\u1ebfc ba l\\u00f4 m\\u00e0u xanh n\\u01b0\\u1edbc bi\\u1ec3n.\"},{\"question_id\":8,\"version\":1,\"question_text\":\"\\u0110\\u1ecdc \\u0111o\\u1ea1n ng\\u1eafn: \\\"Anna is 9 years old. She lives in Da Nang with her parents.\\\" Anna s\\u1ed1ng \\u1edf \\u0111\\u00e2u?\",\"question_type\":\"mcq\",\"options\":[\"H\\u00e0 N\\u1ed9i\",\"\\u0110\\u00e0 N\\u1eb5ng\",\"H\\u1ed3 Ch\\u00ed Minh\",\"Nha Trang\"],\"skill\":\"reading\",\"difficulty\":\"A1\",\"user_answer\":\"\",\"correct_answer\":\"\\u0110\\u00e0 N\\u1eb5ng\",\"is_correct\":false,\"is_answered\":false,\"explanation\":\"\\u0110o\\u1ea1n v\\u0103n n\\u00eau r\\u00f5: \\\"She lives in Da Nang\\\".\"},{\"question_id\":49,\"version\":1,\"question_text\":\"\\u0110\\u1ecdc bi\\u1ec3n b\\u00e1o t\\u1ea1i th\\u01b0 vi\\u1ec7n: \\\"SILENCE PLEASE - Study Area\\\". Bi\\u1ec3n b\\u00e1o n\\u00e0y y\\u00eau c\\u1ea7u \\u0111i\\u1ec1u g\\u00ec?\",\"question_type\":\"reading_comprehension\",\"options\":[\"Kh\\u00f4ng \\u0111\\u01b0\\u1ee3c \\u0103n u\\u1ed1ng\",\"Gi\\u1eef y\\u00ean l\\u1eb7ng\",\"T\\u1eaft m\\u00e1y t\\u00ednh\",\"Kh\\u00f4ng mang s\\u00e1