INSERT INTO `courses` (`id`, `title`, `slug`, `description`, `thumbnail`, `level`, `target_audience`, `order`, `is_published`, `allow_self_enrollment`, `enrollment_key`, `enrollment_duration_days`, `grading_scale`, `passing_grade`, `certificate_enabled`, `badge_reward`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'English Basics - Tiếng Anh Giao Tiếp Cơ Bản A1', 'english-basics-a1', 'Khóa học nền tảng toàn diện dành cho người mới bắt đầu hoặc mất gốc tiếng Anh. Học viên sẽ được trang bị hệ thống từ vựng cốt lõi, phát âm chuẩn IPA, ngữ pháp nền tảng và các mẫu câu giao tiếp tự tin trong đời sống hàng ngày.', '/images/course-a1.png', 'A1', NULL, 1, 1, 0, NULL, NULL, 'scale_100', '50.00', 1, NULL, 3, '2026-09-07 02:04:27', '2026-09-07 02:09:21'),
(2, 'English Elementary - Tiếng Anh Sơ Cấp A2', 'english-elementary-a2', 'Khóa học nâng cao vốn từ vựng học thuật và giao tiếp theo tiêu chuẩn CEFR A2. Bạn sẽ học cách diễn đạt sở thích, kể lại các trải nghiệm, miêu tả thời tiết và tự tin mua sắm, gọi món ăn tại nhà hàng quốc tế.', '/images/course-a2.png', 'A2', NULL, 2, 1, 0, NULL, NULL, 'scale_100', '50.00', 1, NULL, 3, '2026-09-07 02:04:27', '2026-09-07 02:09:55');

