(1, 'mock_test_a1', 'Đề Thi Thử Toàn Diện 4 Kỹ Năng A1 - Sơ Cấp (Full Simulation)', 'full_mock', 'A1', 8, 15, 35, 'Mô phỏng bài thi thực tế chuẩn CEFR A1 gồm đầy đủ 4 kỹ năng: Nghe (3 câu), Đọc (3 câu), Viết (1 bài), Nói (1 phần).', '{\"listening\":3,\"reading\":3,\"writing\":1,\"speaking\":1}', NULL, 1, 1, '2026-09-07 02:04:27', '2026-09-07 16:36:09'),
(2, 'mock_test_a2', 'Đề Thi Thử Toàn Diện 4 Kỹ Năng A2 - Tiền Trung Cấp (Full Simulation)', 'full_mock', 'A2', 8, 20, 45, 'Mô phỏng bài thi thực tế chuẩn CEFR A2 gồm đầy đủ 4 kỹ năng: Nghe (3 câu), Đọc (3 câu), Viết (1 bài), Nói (1 phần).', '{\"listening\":3,\"reading\":3,\"writing\":1,\"speaking\":1}', NULL, 1, 1, '2026-09-07 02:04:27', '2026-09-07 16:36:09'),
(3, 'mock_test_b1', 'Đề Thi Thử Toàn Diện 4 Kỹ Năng B1 - Trung Cấp (Full Simulation)', 'full_mock', 'B1', 8, 25, 60, 'Mô phỏng bài thi thực tế chuẩn CEFR B1 gồm đầy đủ 4 kỹ năng: Nghe (3 câu), Đọc (3 câu), Viết (1 bài), Nói (1 phần).', '{\"listening\":3,\"reading\":3,\"writing\":1,\"speaking\":1}', NULL, 1, 1, '2026-09-07 02:04:27', '2026-09-07 16:36:09'),
(4, 'mock_test_national', 'Đề Khảo Thí Quốc Tế ESL Full 4 Kỹ Năng (Standard CEFR Placement)', 'full_mock', 'Mixed', 12, 30, 80, 'Đề thi phân định năng lực chuẩn hóa quốc tế với 12 câu hỏi phân bố đều cho cả 4 kỹ năng: Nghe, Đọc, Viết, Nói.', '{\"listening\":4,\"reading\":4,\"writing\":2,\"speaking\":2}', NULL, 1, 1, '2026-09-07 02:04:27', '2026-09-07 16:36:09'),
(13, 'reading_test_01', 'Đề 01: Đọc hiểu Đoạn văn Ngắn & Nhận diện Chi tiết', 'reading', 'A1', 2, 6, 10, 'Đọc đoạn văn ngắn về nhân vật, đồ vật và tìm thông tin cụ thể.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27'),
(14, 'reading_test_02', 'Đề 02: Phân tích Bảng thông báo & Thói quen hàng ngày', 'reading', 'A2', 2, 8, 15, 'Hiểu nội dung thông báo công cộng, bảo trì thư viện và thời gian biểu sinh hoạt.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27'),
(15, 'reading_test_03', 'Đề 03: Đọc hiểu Học thuật & Lợi ích Học trực tuyến', 'reading', 'B1', 2, 10, 20, 'Phân tích văn bản tin tức, ý chính bài luận và suy luận logic.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27'),
(16, 'reading_test_full', 'Đề Tổng Hợp: Mini-Test Đọc hiểu Chuyên sâu', 'reading', 'Mixed', 6, 15, 25, 'Kiểm tra kỹ năng Skimming & Scanning qua nhiều thể loại văn bản đa dạng.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27'),
(17, 'listening_test_01', 'Đề 01: Giao tiếp Cơ bản - Lời cảm ơn & Hỏi giờ', 'listening', 'A1', 2, 5, 10, 'Phản xạ với câu hỏi thời gian và các lời chào giao tiếp lịch sự.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27'),
(18, 'listening_test_02', 'Đề 02: Tình huống Thực tế - Chỉ đường & Đặt phòng', 'listening', 'A2', 2, 8, 15, 'Nghe hiểu hướng dẫn rẽ đường và thông tin số đêm khi đặt phòng khách sạn.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27'),
(19, 'listening_test_03', 'Đề 03: Tình huống Nâng cao - Thông báo Sân bay & Phỏng vấn', 'listening', 'B1', 2, 10, 20, 'Nghe thông báo hoãn chuyến bay sân bay và câu hỏi trong phỏng vấn tuyển dụng.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27'),
(20, 'listening_test_full', 'Đề Tổng Hợp: Mini-Test Nghe hiểu Tình huống Toàn diện', 'listening', 'Mixed', 6, 15, 25, 'Bộ đề nghe hiểu tổng hợp đủ các tình huống đời sống và học thuật.', NULL, NULL, 1, 3, '2026-09-07 02:04:27', '2026-09-07 02:04:27');

