INSERT INTO `lessons` (`id`, `course_id`, `title`, `description`, `summary`, `order`, `estimated_minutes`, `unlock_condition_score`, `is_free_trial`, `is_visible`, `created_at`, `updated_at`) VALUES
(1, 1, 'Bài 1: Chào hỏi, Làm quen & Tự giới thiệu bản thân', 'Nắm vững các câu chào hỏi trang trọng và thân mật, cách giới thiệu tên tuổi, nghề nghiệp và quê quán.', NULL, 1, 20, 0, 1, 1, '2026-09-07 02:04:27', '2026-09-07 07:56:13'),
(2, 1, 'Bài 2: Gia đình & Nghề nghiệp (Family & Occupations)', 'Mở rộng vốn từ vựng về các mối quan hệ gia đình, các ngành nghề thông dụng và cách sử dụng tính từ sở hữu.', NULL, 2, 20, 60, 0, 1, '2026-09-07 02:04:27', '2026-09-07 02:07:05'),
(3, 1, 'Bài 3: Số đếm, Thời gian & Thói quen hàng ngày', 'Học cách đọc số đếm, ngày tháng, cách nói giờ và các giới từ chỉ thời gian thông dụng (in, on, at).', NULL, 3, 20, 60, 0, 1, '2026-09-07 02:04:27', '2026-09-07 02:07:05'),
(4, 2, 'Bài 1: Sở thích, Thể thao & Hoạt động giải trí', 'Khám phá các từ vựng về sở thích, cách sử dụng thì Hiện tại đơn và các trạng từ chỉ tần suất.', NULL, 1, 20, 0, 1, 1, '2026-09-07 02:04:27', '2026-09-07 02:07:05'),
(5, 2, 'Bài 2: Thời tiết, Khí hậu & Kế hoạch tương lai', 'Miêu tả các hiện tượng thời tiết, 4 mùa trong năm và cách diễn đạt dự định tương lai với cấu trúc \"Be going to\".', NULL, 2, 20, 60, 0, 1, '2026-09-07 02:04:27', '2026-09-07 02:07:05'),
(6, 2, 'Bài 3: Mua sắm, Ăn uống & Gọi món tại Nhà hàng', 'Học các mẫu câu giao tiếp tự tin khi đi mua sắm, hỏi giá cả, gọi món ăn và cách phân biệt danh từ đếm được / không đếm được.', NULL, 3, 20, 60, 0, 1, '2026-09-07 02:04:27', '2026-09-07 02:07:05');

