INSERT INTO `question_banks` (`id`, `course_id`, `skill`, `difficulty`, `version`, `parent_id`, `question_type`, `question_text`, `options`, `audio_url`, `correct_answer`, `explanation`, `meta_data`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, NULL, 'vocabulary', 'A1', 1, NULL, 'mcq', 'Từ nào sau đây mang ý nghĩa là \"Chào buổi sáng\"?', '[\"Good evening\",\"Good morning\",\"Good afternoon\",\"Good night\"]', NULL, 'Good morning', '\"Good morning\" là lời chào buổi sáng (từ lúc thức dậy đến trước 12h trưa).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(2, NULL, 'vocabulary', 'A1', 1, NULL, 'mcq', 'Thành viên nào trong gia đình được gọi là \"Brother\"?', '[\"B\\u1ed1\",\"M\\u1eb9\",\"Anh ho\\u1eb7c em trai\",\"Ch\\u1ecb ho\\u1eb7c em g\\u00e1i\"]', NULL, 'Anh hoặc em trai', 'Brother = Anh/Em trai. Sister = Chị/Em gái. Father = Bố. Mother = Mẹ.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(3, NULL, 'vocabulary', 'A1', 1, NULL, 'mcq', 'Số \"15\" được viết bằng tiếng Anh là gì?', '[\"Fifty\",\"Fifteen\",\"Five\",\"Fiveteen\"]', NULL, 'Fifteen', '15 = Fifteen. 50 = Fifty. 5 = Five.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(4, NULL, 'grammar', 'A1', 1, NULL, 'mcq', 'Chọn dạng đúng của động từ to be: \"I ___ a student at ESL.\"', '[\"is\",\"are\",\"am\",\"be\"]', NULL, 'am', 'Chủ ngữ \"I\" luôn đi với động từ to be \"am\" ở thì hiện tại đơn.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(5, NULL, 'grammar', 'A1', 1, NULL, 'mcq', 'Điền vào chỗ trống: \"This is My. ___ is my classmate.\"', '[\"He\",\"She\",\"They\",\"It\"]', NULL, 'She', 'My là tên con gái (nữ), đại từ nhân xưng thay thế là \"She\".', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(6, NULL, 'grammar', 'A1', 1, NULL, 'mcq', 'Chọn tính từ sở hữu thích hợp: \"We love ___ school.\"', '[\"our\",\"their\",\"his\",\"her\"]', NULL, 'our', 'Chủ ngữ \"We\" (chúng tôi) tương ứng với tính từ sở hữu \"our\" (của chúng tôi).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(7, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Đọc câu sau: \"Tom has a blue backpack and two pens.\" Tom có cái gì màu xanh nước biển?', '[\"Hai chi\\u1ebfc b\\u00fat\",\"M\\u1ed9t chi\\u1ebfc ba l\\u00f4\",\"M\\u1ed9t quy\\u1ec3n s\\u00e1ch\",\"M\\u1ed9t \\u0111\\u00f4i gi\\u00e0y\"]', NULL, 'Một chiếc ba lô', '\"Blue backpack\" có nghĩa là chiếc ba lô màu xanh nước biển.', NULL, '2026-09-07 02:04:27', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(8, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Đọc đoạn ngắn: \"Anna is 9 years old. She lives in Da Nang with her parents.\" Anna sống ở đâu?', '[\"H\\u00e0 N\\u1ed9i\",\"\\u0110\\u00e0 N\\u1eb5ng\",\"H\\u1ed3 Ch\\u00ed Minh\",\"Nha Trang\"]', NULL, 'Đà Nẵng', 'Đoạn văn nêu rõ: \"She lives in Da Nang\".', NULL, '2026-09-07 02:04:27', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(9, NULL, 'listening', 'A1', 1, NULL, 'mcq', '[Âm thanh] Người nói hỏi: \"What time is it?\" - Câu trả lời phù hợp nhất là:', '[\"I am fine, thank you.\",\"It is 8 o\'clock.\",\"My name is John.\",\"Yes, I do.\"]', NULL, 'It is 8 o\'clock.', '\"What time is it?\" dùng để hỏi giờ, câu trả lời là \"It is 8 o\'clock\" (Bây giờ là 8 giờ).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(10, NULL, 'listening', 'A1', 1, NULL, 'mcq', '[Giao tiếp] Khi ai đó nói \"Thank you very much!\", bạn sẽ đáp lại như thế nào?', '[\"Goodbye!\",\"You\'re welcome!\",\"See you later.\",\"I am sorry.\"]', NULL, 'You\'re welcome!', '\"You\'re welcome!\" (Không có gì đâu!) là câu đáp lại phổ biến và lịch sự nhất khi được cảm ơn.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(11, NULL, 'vocabulary', 'A2', 1, NULL, 'mcq', 'Từ nào đồng nghĩa với từ \"Delicious\" (ngon miệng)?', '[\"Tasty\",\"Terrible\",\"Expensive\",\"Boring\"]', NULL, 'Tasty', 'Delicious và Tasty đều có nghĩa là thơm ngon. Terrible = tồi tệ, Boring = nhàm chán.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(12, NULL, 'vocabulary', 'A2', 1, NULL, 'mcq', 'Người làm công việc chăm sóc răng miệng được gọi là:', '[\"Architect\",\"Dentist\",\"Engineer\",\"Journalist\"]', NULL, 'Dentist', 'Dentist = Nha sĩ. Architect = Kiến trúc sư. Engineer = Kỹ sư.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(13, NULL, 'vocabulary', 'A2', 1, NULL, 'mcq', 'Trái nghĩa với từ \"Crowded\" (đông đúc) là từ nào?', '[\"Busy\",\"Noisy\",\"Quiet\",\"Empty\"]', NULL, 'Empty', 'Crowded = đông đúc, chật kín. Empty = vắng vẻ, trống trải.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(14, NULL, 'grammar', 'A2', 1, NULL, 'mcq', 'Chọn đáp án đúng ở thì Quá khứ đơn: \"Yesterday, we ___ to the national museum.\"', '[\"go\",\"went\",\"gone\",\"going\"]', NULL, 'went', 'Dấu hiệu \"Yesterday\" chỉ quá khứ đơn, quá khứ của \"go\" là \"went\".', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(15, NULL, 'grammar', 'A2', 1, NULL, 'mcq', 'Chọn liên từ thích hợp: \"She was tired, ___ she finished her homework before sleeping.\"', '[\"because\",\"but\",\"so\",\"although\"]', NULL, 'but', '\"But\" (nhưng) thể hiện sự tương phản: Dù mệt nhưng cô ấy vẫn hoàn thành bài tập.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(16, NULL, 'grammar', 'A2', 1, NULL, 'mcq', 'Chọn dạng so sánh hơn: \"Travelling by train is ___ than travelling by bus.\"', '[\"more comfortable\",\"comfortabler\",\"most comfortable\",\"as comfortable\"]', NULL, 'more comfortable', 'Comfortable là tính từ dài (3 âm tiết), so sánh hơn dùng \"more + adj + than\".', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(17, NULL, 'reading', 'A2', 1, NULL, 'mcq', 'Đọc thông báo: \"Library will be closed this Friday for maintenance.\" Bạn không thể làm gì vào thứ Sáu?', '[\"M\\u01b0\\u1ee3n s\\u00e1ch t\\u1ea1i th\\u01b0 vi\\u1ec7n\",\"\\u0110i h\\u1ecdc th\\u1ec3 d\\u1ee5c\",\"\\u0102n tr\\u01b0a t\\u1ea1i c\\u0103ng tin\",\"\\u0110i xe bu\\u00fdt\"]', NULL, 'Mượn sách tại thư viện', 'Thư viện (Library) đóng cửa để bảo trì nên học sinh không thể đến mượn sách.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(18, NULL, 'reading', 'A2', 1, NULL, 'mcq', 'Đọc đoạn văn: \"Peter gets up at 6 AM, exercises for 30 minutes, then takes a shower.\" Peter làm gì sau khi tập thể dục?', '[\"\\u0102n s\\u00e1ng\",\"Th\\u1ee9c d\\u1eady\",\"\\u0110i t\\u1eafm\",\"\\u0110i h\\u1ecdc\"]', NULL, 'Đi tắm', '\"then takes a shower\" = sau đó anh ấy đi tắm.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(19, NULL, 'listening', 'A2', 1, NULL, 'mcq', '[Chỉ đường] Khi được hướng dẫn \"Take the second turning on your left\", bạn cần rẽ ở đâu?', '[\"R\\u1ebd tr\\u00e1i \\u1edf ng\\u00e3 r\\u1ebd th\\u1ee9 nh\\u1ea5t\",\"R\\u1ebd tr\\u00e1i \\u1edf ng\\u00e3 r\\u1ebd th\\u1ee9 hai\",\"R\\u1ebd ph\\u1ea3i \\u1edf ng\\u00e3 r\\u1ebd th\\u1ee9 hai\",\"\\u0110i th\\u1eb3ng qua hai ng\\u00e3 t\\u01b0\"]', NULL, 'Rẽ trái ở ngã rẽ thứ hai', 'Second turning on your left = ngã rẽ thứ hai bên tay trái.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(20, NULL, 'listening', 'A2', 1, NULL, 'mcq', '[Đặt phòng] \"I would like to book a double room for two nights.\" Khách muốn đặt phòng cho mấy đêm?', '[\"1 \\u0111\\u00eam\",\"2 \\u0111\\u00eam\",\"3 \\u0111\\u00eam\",\"1 tu\\u1ea7n\"]', NULL, '2 đêm', '\"for two nights\" nghĩa là đặt phòng trong 2 đêm.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(21, NULL, 'vocabulary', 'B1', 1, NULL, 'mcq', 'Chọn từ thích hợp: \"Regular exercise is extremely ___ for both mental and physical health.\"', '[\"harmful\",\"beneficial\",\"useless\",\"dangerous\"]', NULL, 'beneficial', 'Beneficial = có lợi, hữu ích. Harmful = có hại. Useless = vô dụng.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(22, NULL, 'vocabulary', 'B1', 1, NULL, 'mcq', 'Cụm động từ \"Look forward to\" có nghĩa là gì?', '[\"Ch\\u0103m s\\u00f3c ai \\u0111\\u00f3\",\"T\\u00ecm ki\\u1ebfm th\\u00f4ng tin\",\"H\\u00e1o h\\u1ee9c mong \\u0111\\u1ee3i \\u0111i\\u1ec1u g\\u00ec\",\"Xem th\\u01b0\\u1eddng ai \\u0111\\u00f3\"]', NULL, 'Háo hức mong đợi điều gì', 'Look forward to + V-ing / Noun mang nghĩa là mong chờ, háo hức chờ đợi.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(23, NULL, 'vocabulary', 'B1', 1, NULL, 'mcq', 'Thuật ngữ \"Renewable energy\" chỉ loại năng lượng nào?', '[\"N\\u0103ng l\\u01b0\\u1ee3ng h\\u00f3a th\\u1ea1ch\",\"N\\u0103ng l\\u01b0\\u1ee3ng t\\u00e1i t\\u1ea1o\",\"N\\u0103ng l\\u01b0\\u1ee3ng h\\u1ea1t nh\\u00e2n\",\"Kh\\u00ed \\u0111\\u1ed1t t\\u1ef1 nhi\\u00ean\"]', NULL, 'Năng lượng tái tạo', 'Renewable energy = Năng lượng tái tạo (mặt trời, gió, thủy triều).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(24, NULL, 'grammar', 'B1', 1, NULL, 'mcq', 'Chọn thì Hiện tại hoàn thành phù hợp: \"She ___ in this company since 2018.\"', '[\"has worked\",\"worked\",\"is working\",\"works\"]', NULL, 'has worked', 'Dấu hiệu \"since + mốc thời gian\" dùng thì Hiện tại hoàn thành (have/has + V3/ed).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(25, NULL, 'grammar', 'B1', 1, NULL, 'mcq', 'Câu điều kiện loại 2: \"If I ___ a million dollars, I would travel around the world.\"', '[\"have\",\"had\",\"will have\",\"would have\"]', NULL, 'had', 'Cấu trúc câu điều kiện loại 2: If + S + V-ed/V2 (were), S + would + V-inf.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(26, NULL, 'grammar', 'B1', 1, NULL, 'mcq', 'Mệnh đề quan hệ: \"The man ___ wrote this book won an international award.\"', '[\"which\",\"who\",\"whom\",\"whose\"]', NULL, 'who', '\"The man\" là danh từ chỉ người đóng vai trò chủ ngữ trong mệnh đề, dùng đại từ quan hệ \"who\".', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(27, NULL, 'reading', 'B1', 1, NULL, 'mcq', 'Đọc câu: \"Despite the heavy rain, the soccer match continued without interruption.\" Ý chính của câu là gì?', '[\"Tr\\u1eadn \\u0111\\u1ea5u b\\u1ecb ho\\u00e3n do m\\u01b0a l\\u1edbn\",\"Tr\\u1eadn \\u0111\\u1ea5u v\\u1eabn ti\\u1ebfp t\\u1ee5c d\\u00f9 tr\\u1eddi m\\u01b0a to\",\"Kh\\u00e1n gi\\u1ea3 b\\u1ecf v\\u1ec1 v\\u00ec m\\u01b0a\",\"Tr\\u1eadn \\u0111\\u1ea5u b\\u1ecb h\\u1ee7y b\\u1ecf\"]', NULL, 'Trận đấu vẫn tiếp tục dù trời mưa to', '\"Despite the heavy rain... continued without interruption\" = Mặc cho mưa lớn, trận đấu vẫn diễn ra liên tục.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(28, NULL, 'reading', 'B1', 1, NULL, 'mcq', 'Đọc đoạn: \"Online learning offers great flexibility, allowing students to study at their own pace anywhere.\" Lợi ích chính của học trực tuyến ở đây là gì?', '[\"Mi\\u1ec5n ph\\u00ed ho\\u00e0n to\\u00e0n h\\u1ecdc ph\\u00ed\",\"S\\u1ef1 linh ho\\u1ea1t v\\u00e0 t\\u1ef1 ch\\u1ee7 v\\u1ec1 th\\u1eddi gian, \\u0111\\u1ecba \\u0111i\\u1ec3m\",\"\\u0110\\u01b0\\u1ee3c g\\u1eb7p tr\\u1ef1c ti\\u1ebfp gi\\u1ea3ng vi\\u00ean\",\"Kh\\u00f4ng c\\u1ea7n l\\u00e0m b\\u00e0i t\\u1eadp v\\u1ec1 nh\\u00e0\"]', NULL, 'Sự linh hoạt và tự chủ về thời gian, địa điểm', '\"Flexibility, allowing students to study at their own pace anywhere\" = Tính linh hoạt, học theo tốc độ bản thân ở bất kỳ đâu.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(29, NULL, 'listening', 'B1', 1, NULL, 'mcq', '[Thông báo sân bay] \"Flight VN123 to Da Nang is delayed by 45 minutes due to adverse weather conditions.\" Chuyến bay bị hoãn vì lý do gì?', '[\"S\\u1ef1 c\\u1ed1 k\\u1ef9 thu\\u1eadt m\\u00e1y bay\",\"\\u0110i\\u1ec1u ki\\u1ec7n th\\u1eddi ti\\u1ebft x\\u1ea5u\",\"Thi\\u1ebfu phi h\\u00e0nh \\u0111o\\u00e0n\",\"Qu\\u00e1 t\\u1ea3i \\u0111\\u01b0\\u1eddng b\\u0103ng\"]', NULL, 'Điều kiện thời tiết xấu', '\"Adverse weather conditions\" nghĩa là điều kiện thời tiết bất lợi / xấu.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(30, NULL, 'listening', 'B1', 1, NULL, 'mcq', '[Phỏng vấn] \"Could you tell me about a challenge you faced and how you overcame it?\" Người phỏng vấn muốn biết về điều gì?', '[\"M\\u1ee9c l\\u01b0\\u01a1ng mong mu\\u1ed1n c\\u1ee7a b\\u1ea1n\",\"M\\u1ed9t th\\u1eed th\\u00e1ch v\\u00e0 c\\u00e1ch b\\u1ea1n v\\u01b0\\u1ee3t qua n\\u00f3\",\"B\\u1eb1ng c\\u1ea5p h\\u1ecdc t\\u1eadp c\\u1ee7a b\\u1ea1n\",\"Gia \\u0111\\u00ecnh v\\u00e0 ng\\u01b0\\u1eddi th\\u00e2n c\\u1ee7a b\\u1ea1n\"]', NULL, 'Một thử thách và cách bạn vượt qua nó', '\"A challenge you faced and how you overcame it\" = thử thách bạn gặp phải và cách bạn đã vượt qua nó.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(31, NULL, 'vocabulary', 'A2', 1, NULL, 'multiple_select', 'Chọn 2 từ đồng nghĩa hoặc liên quan trực tiếp đến \"Healthy\" (Lành mạnh / Khỏe khoắn):', '[\"Fit\",\"Strong\",\"Tired\",\"Sick\"]', NULL, '[\"Fit\",\"Strong\"]', '\"Fit\" (cân đối, khỏe mạnh) và \"Strong\" (mạnh mẽ) là 2 từ liên quan trực tiếp đến sức khỏe tốt.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(32, NULL, 'grammar', 'A2', 1, NULL, 'fill_blank', 'Điền dạng Quá khứ đơn (Past Simple) của động từ \"buy\": \"Yesterday, I ___ a new English dictionary.\"', '[]', NULL, 'bought', 'Động từ bất quy tắc của \"buy\" ở quá khứ là \"bought\".', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(33, NULL, 'grammar', 'A1', 1, NULL, 'word_ordering', 'Bấm chọn các từ bên dưới để sắp xếp thành câu hoàn chỉnh đúng ngữ pháp:', '[\"English\",\"every\",\"I\",\"study\",\"day\"]', NULL, 'I study English every day', 'Cấu trúc câu khẳng định hiện tại đơn: Chủ ngữ (I) + Động từ (study) + Tân ngữ (English) + Trạng từ chỉ thời gian (every day).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(34, NULL, 'vocabulary', 'B1', 1, NULL, 'matching', 'Nối các thuật ngữ môi trường sau với định nghĩa tiếng Việt tương ứng:', '{\"left\":{\"Ecosystem\":\"Ecosystem\",\"Biodiversity\":\"Biodiversity\",\"Conservation\":\"Conservation\"},\"right\":[\"H\\u1ec7 sinh th\\u00e1i\",\"\\u0110a d\\u1ea1ng sinh h\\u1ecdc\",\"B\\u1ea3o t\\u1ed3n thi\\u00ean nhi\\u00ean\"]}', NULL, '{\"Ecosystem\":\"H\\u1ec7 sinh th\\u00e1i\",\"Biodiversity\":\"\\u0110a d\\u1ea1ng sinh h\\u1ecdc\",\"Conservation\":\"B\\u1ea3o t\\u1ed3n thi\\u00ean nhi\\u00ean\"}', 'Ecosystem = Hệ sinh thái, Biodiversity = Đa dạng sinh học, Conservation = Sự bảo tồn.', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(35, NULL, 'reading', 'B1', 1, NULL, 'true_false', 'Đọc câu sau: \"Solar panels convert sunlight directly into clean electricity without producing greenhouse gases.\" Nhận định: \"Năng lượng mặt trời không tạo ra khí nhà kính.\"', '[\"True\",\"False\",\"Not Given\"]', NULL, 'True', 'Đoạn văn nêu rõ \"without producing greenhouse gases\" nghĩa là không sinh ra khí thải nhà kính, do đó nhận định là True (Đúng).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(36, NULL, 'listening', 'A2', 1, NULL, 'audio_listening', 'Nghe câu thông báo: \"The next flight to Tokyo departs from Gate 14.\" Chuyến bay đi Tokyo khởi hành tại cổng nào?', '[\"Gate 4\",\"Gate 14\",\"Gate 40\",\"Gate 24\"]', NULL, 'Gate 14', 'Trong thông báo nêu rõ \"Gate 14\" (Cổng số 14).', NULL, '2026-09-07 02:04:27', '2026-09-07 02:04:27', NULL),
(37, NULL, 'speaking', 'A1', 1, NULL, 'pronunciation_speech', 'Luyện phát âm chuẩn câu giao tiếp sau bằng micro:\n\n\"Good morning, nice to meet you\"', '[]', NULL, 'Good morning, nice to meet you', 'Phát âm chuẩn /ɡʊd ˈmɔːrnɪŋ naɪs tuː miːt juː/.', NULL, '2026-09-07 02:04:27', '2026-09-07 08:43:19', NULL),
(38, NULL, 'listening', 'A1', 1, NULL, 'mcq', '[Âm thanh] Người nói hỏi: \"Where are you from?\" - Câu trả lời chính xác là:', '[\"I am from Vietnam.\",\"I am 20 years old.\",\"I like coffee.\",\"I am a student.\"]', NULL, 'I am from Vietnam.', '\"Where are you from?\" hỏi về quê quán / xuất xứ, câu trả lời là \"I am from Vietnam\".', NULL, '2026-09-07 08:43:19', '2026-09-07 08:43:19', NULL),
(39, NULL, 'listening', 'A1', 1, NULL, 'mcq', '[Âm thanh] Nghe đoạn hội thoại: \"How do you spell your name?\" - \"It\'s J-O-H-N.\" Tên người nói là gì?', '[\"John\",\"Jane\",\"Jack\",\"James\"]', NULL, 'John', 'Đoạn đánh vần rõ ràng J-O-H-N là John.', NULL, '2026-09-07 08:43:19', '2026-09-07 08:43:19', NULL),
(40, NULL, 'listening', 'A1', 1, NULL, 'listening_comprehension', 'Nghe thông báo tại nhà ga xe lửa: \"The train to Oxford will depart from Platform 3 in five minutes.\" Tàu đi Oxford khởi hành tại sân ga nào?', '[\"Platform 1\",\"Platform 2\",\"Platform 3\",\"Platform 5\"]', NULL, 'Platform 3', 'Thông báo nêu rõ: \"depart from Platform 3\" (khởi hành tại sân ga số 3).', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(41, NULL, 'listening', 'A1', 1, NULL, 'listening_comprehension', 'Nghe câu hỏi tại quầy lễ tân: \"May I have your room key, please?\" Người nói đang yêu cầu điều gì?', '[\"H\\u1ed9 chi\\u1ebfu\",\"Ch\\u00eca kh\\u00f3a ph\\u00f2ng\",\"S\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i\",\"H\\u00f3a \\u0111\\u01a1n thanh to\\u00e1n\"]', NULL, 'Chìa khóa phòng', '\"Room key\" có nghĩa là chìa khóa phòng khách sạn.', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(42, NULL, 'listening', 'A1', 1, NULL, 'listening_comprehension', 'Nghe đoạn hội thoại mua sắm: \"How much is this blue shirt?\" - \"It is twenty-five dollars.\" Chiếc áo sơ mi có giá bao nhiêu?', '[\"$15\",\"$20\",\"$25\",\"$35\"]', NULL, '$25', 'Người bán trả lời: \"twenty-five dollars\" ($25).', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(43, NULL, 'listening', 'A2', 1, NULL, 'listening_comprehension', 'Nghe tin nhắn thoại: \"Hi Tom, our meeting tomorrow has been moved from 9:00 AM to 10:30 AM in Room 204.\" Cuộc họp dời sang mấy giờ?', '[\"9:00 AM\",\"9:30 AM\",\"10:00 AM\",\"10:30 AM\"]', NULL, '10:30 AM', 'Lời nhắn: \"moved from 9:00 AM to 10:30 AM\" (dời sang 10 giờ 30 sáng).', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(44, NULL, 'listening', 'A2', 1, NULL, 'listening_comprehension', 'Nghe chỉ đường: \"Go straight for two blocks, then turn left at the bookstore. The post office is on your right.\" Bưu điện nằm ở đâu?', '[\"B\\u00ean tr\\u00e1i nh\\u00e0 s\\u00e1ch\",\"B\\u00ean ph\\u1ea3i sau khi r\\u1ebd tr\\u00e1i \\u1edf nh\\u00e0 s\\u00e1ch\",\"\\u0110\\u1ed1i di\\u1ec7n s\\u00e2n v\\u1eadn \\u0111\\u1ed9ng\",\"\\u1ede ng\\u00e3 t\\u01b0 th\\u1ee9 nh\\u1ea5t\"]', NULL, 'Bên phải sau khi rẽ trái ở nhà sách', 'Chỉ dẫn: đi thẳng 2 dãy nhà, rẽ trái tại hiệu sách, bưu điện nằm bên tay phải (\"on your right\").', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(45, NULL, 'listening', 'A2', 1, NULL, 'listening_comprehension', 'Nghe thông báo thời tiết: \"Expect heavy rain this afternoon with temperatures dropping to 18 degrees Celsius. Don\'t forget your umbrella.\" Người nghe được khuyên nên mang theo gì?', '[\"K\\u00ednh r\\u00e2m\",\"\\u00c1o kho\\u00e1c d\\u00e0y\",\"\\u00d4 \\/ d\\u00f9\",\"N\\u00f3n b\\u1ea3o hi\\u1ec3m\"]', NULL, 'Ô / dù', '\"Don\'t forget your umbrella\" nghĩa là đừng quên mang ô/dù che mưa.', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(46, NULL, 'listening', 'B1', 1, NULL, 'listening_comprehension', 'Nghe đoạn trao đổi công việc: \"Due to the unexpected budget cuts, the marketing department will postpone the promotional campaign until next quarter.\" Kế hoạch tiếp thị bị ảnh hưởng như thế nào?', '[\"B\\u1ecb h\\u1ee7y b\\u1ecf v\\u0129nh vi\\u1ec5n\",\"Ho\\u00e3n l\\u1ea1i sang qu\\u00fd t\\u1edbi\",\"T\\u0103ng g\\u1ea5p \\u0111\\u00f4i ng\\u00e2n s\\u00e1ch\",\"Chuy\\u1ec3n giao cho \\u0111\\u1ed1i t\\u00e1c\"]', NULL, 'Hoãn lại sang quý tới', '\"postpone the promotional campaign until next quarter\" có nghĩa là hoãn chiến dịch quảng bá đến quý sau.', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(47, NULL, 'listening', 'B1', 1, NULL, 'listening_comprehension', 'Nghe thông báo sân bay: \"Passengers on flight VN384 to Seoul please proceed to Gate 18 immediately for final boarding.\" Hành khách cần làm gì?', '[\"L\\u1ea5y h\\u00e0nh l\\u00fd k\\u00fd g\\u1eedi\",\"\\u0110\\u1ebfn C\\u1ed5ng 18 ngay l\\u1eadp t\\u1ee9c \\u0111\\u1ec3 l\\u00ean m\\u00e1y bay\",\"\\u0110\\u1ed5i v\\u00e9 t\\u1ea1i qu\\u1ea7y ch\\u0103m s\\u00f3c kh\\u00e1ch h\\u00e0ng\",\"Ch\\u1edd ki\\u1ec3m tra an ninh b\\u1ed5 sung\"]', NULL, 'Đến Cổng 18 ngay lập tức để lên máy bay', '\"proceed to Gate 18 immediately for final boarding\" có nghĩa là khẩn trương đến Cổng 18 để lên máy bay.', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(48, NULL, 'listening', 'B2', 1, NULL, 'listening_comprehension', 'Nghe trích đoạn bài giảng kinh tế: \"The central bank decided to lower interest rates to stimulate consumer spending and encourage business investment amidst inflationary pressures.\" Mục tiêu của việc giảm lãi suất là gì?', '[\"Ki\\u1ec3m so\\u00e1t t\\u1ef7 gi\\u00e1 h\\u1ed1i \\u0111o\\u00e1i\",\"K\\u00edch th\\u00edch chi ti\\u00eau ti\\u00eau d\\u00f9ng v\\u00e0 khuy\\u1ebfn kh\\u00edch \\u0111\\u1ea7u t\\u01b0 kinh doanh\",\"Gi\\u1ea3m thu\\u1ebf thu nh\\u1eadp doanh nghi\\u1ec7p\",\"H\\u1ea1n ch\\u1ebf nh\\u1eadp kh\\u1ea9u h\\u00e0ng ti\\u00eau d\\u00f9ng\"]', NULL, 'Kích thích chi tiêu tiêu dùng và khuyến khích đầu tư kinh doanh', '\"to stimulate consumer spending and encourage business investment\" nói rõ mục đích kích cầu tiêu dùng và thúc đẩy đầu tư.', '{\"audio_url\":\"https:\\/\\/assets.mixkit.co\\/active_storage\\/sfx\\/2869\\/2869-preview.mp3\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(49, NULL, 'reading', 'A1', 1, NULL, 'reading_comprehension', 'Đọc biển báo tại thư viện: \"SILENCE PLEASE - Study Area\". Biển báo này yêu cầu điều gì?', '[\"Kh\\u00f4ng \\u0111\\u01b0\\u1ee3c \\u0103n u\\u1ed1ng\",\"Gi\\u1eef y\\u00ean l\\u1eb7ng\",\"T\\u1eaft m\\u00e1y t\\u00ednh\",\"Kh\\u00f4ng mang s\\u00e1ch ra ngo\\u00e0i\"]', NULL, 'Giữ yên lặng', '\"Silence please\" nghĩa là xin vui lòng giữ trật tự/im lặng.', '{\"passage_title\":\"Bi\\u1ec3n b\\u00e1o th\\u01b0 vi\\u1ec7n\",\"passage_content\":\"NOTICE:\\\\nSILENCE PLEASE\\\\nThis is a designated quiet study area. Please turn off phone ringers.\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(50, NULL, 'reading', 'A1', 1, NULL, 'reading_comprehension', 'Đọc thông báo cửa hàng: \"OPEN Monday - Saturday: 8:00 AM - 9:00 PM. CLOSED on Sundays.\" Cửa hàng đóng cửa vào ngày nào?', '[\"Th\\u1ee9 Hai\",\"Th\\u1ee9 B\\u1ea3y\",\"Ch\\u1ee7 Nh\\u1eadt\",\"T\\u1ea5t c\\u1ea3 c\\u00e1c ng\\u00e0y l\\u1ec5\"]', NULL, 'Chủ Nhật', '\"CLOSED on Sundays\" nghĩa là đóng cửa vào các ngày Chủ nhật.', '{\"passage_title\":\"Gi\\u1edd m\\u1edf c\\u1eeda\",\"passage_content\":\"STORE HOURS:\\\\nMonday - Saturday: 8:00 AM - 9:00 PM\\\\nSunday: CLOSED\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(51, NULL, 'reading', 'A2', 1, NULL, 'reading_comprehension', 'Đọc email nội bộ: \"Dear Staff, our annual company picnic is scheduled for Saturday, October 15th at Green Lake Park. Transportation will be provided from the office at 7:30 AM.\" Xe đưa đón nhân viên khởi hành lúc mấy giờ?', '[\"6:30 AM\",\"7:00 AM\",\"7:30 AM\",\"8:00 AM\"]', NULL, '7:30 AM', 'Đoạn văn nêu rõ: \"Transportation will be provided from the office at 7:30 AM\".', '{\"passage_title\":\"Company Picnic Announcement\",\"passage_content\":\"Dear Staff,\\\\nOur annual company picnic is scheduled for Saturday, October 15th at Green Lake Park. Free lunch and sports activities will be available for everyone. Transportation will be provided from the office at 7:30 AM.\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(52, NULL, 'reading', 'A2', 1, NULL, 'reading_comprehension', 'Đọc tờ rơi khóa học: \"English for Travel: Learn essential phrases for airports, hotels, and restaurants. 4 weeks, 2 sessions per week. Special 20% discount for early bird registration before May 1st.\" Ưu đãi nào được dành cho người đăng ký sớm trước ngày 1 tháng 5?', '[\"T\\u1eb7ng s\\u00e1ch gi\\u00e1o tr\\u00ecnh mi\\u1ec5n ph\\u00ed\",\"Gi\\u1ea3m 20% h\\u1ecdc ph\\u00ed\",\"H\\u1ecdc th\\u1eed mi\\u1ec5n ph\\u00ed 1 tu\\u1ea7n\",\"\\u0110\\u01b0\\u1ee3c h\\u1ecdc k\\u00e8m 1-1\"]', NULL, 'Giảm 20% học phí', 'Tờ rơi ghi: \"Special 20% discount for early bird registration before May 1st\".', '{\"passage_title\":\"Travel Course Flyer\",\"passage_content\":\"English for Travel Course:\\\\nMaster real-world conversations at international airports, hotels, and dining.\\\\nDuration: 4 weeks (8 classes).\\\\nEarly bird bonus: 20% discount if registered before May 1st.\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(53, NULL, 'reading', 'B1', 1, NULL, 'reading_comprehension', 'Theo đoạn văn, xu hướng làm việc từ xa (remote work) mang lại lợi ích môi trường nổi bật nào?', '[\"T\\u0103ng s\\u1ea3n l\\u01b0\\u1ee3ng ti\\u00eau th\\u1ee5 \\u0111i\\u1ec7n\",\"Gi\\u1ea3m thi\\u1ec3u kh\\u00ed th\\u1ea3i c\\u00e1c-bon do gi\\u1ea3m ph\\u01b0\\u01a1ng ti\\u1ec7n \\u0111i l\\u1ea1i h\\u00e0ng ng\\u00e0y\",\"T\\u0103ng di\\u1ec7n t\\u00edch v\\u0103n ph\\u00f2ng cho thu\\u00ea\",\"Th\\u00fac \\u0111\\u1ea9y s\\u1eed d\\u1ee5ng \\u0111\\u1ed3 nh\\u1ef1a d\\u00f9ng m\\u1ed9t l\\u1ea7n\"]', NULL, 'Giảm thiểu khí thải các-bon do giảm phương tiện đi lại hàng ngày', 'Bài viết nhấn mạnh: \"reducing daily commutes has led to a measurable decline in carbon emissions and urban traffic congestion\".', '{\"passage_title\":\"Environmental Impacts of Remote Work\",\"passage_content\":\"In recent years, the shift toward telecommuting has dramatically reshaped the corporate landscape. Beyond enhancing work-life balance and flexibility for employees, reducing daily commutes has led to a measurable decline in carbon emissions and urban traffic congestion. Studies indicate that companies adopting hybrid models also consume significantly less office electricity and paper.\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(54, NULL, 'reading', 'B1', 1, NULL, 'reading_comprehension', 'Theo đoạn văn, nguyên nhân chính khiến loài ong mật suy giảm quần thể là gì?', '[\"Thi\\u1ebfu ngu\\u1ed3n n\\u01b0\\u1edbc s\\u1ea1ch\",\"S\\u1ef1 k\\u1ebft h\\u1ee3p gi\\u1eefa m\\u1ea5t m\\u00f4i tr\\u01b0\\u1eddng s\\u1ed1ng, thu\\u1ed1c tr\\u1eeb s\\u00e2u v\\u00e0 bi\\u1ebfn \\u0111\\u1ed5i kh\\u00ed h\\u1eadu\",\"S\\u1ef1 gia t\\u0103ng c\\u1ee7a c\\u00e1c lo\\u00e0i chim \\u0103n th\\u1ecbt\",\"Nhi\\u1ec7t \\u0111\\u1ed9 m\\u00f9a \\u0111\\u00f4ng qu\\u00e1 l\\u1ea1nh\"]', NULL, 'Sự kết hợp giữa mất môi trường sống, thuốc trừ sâu và biến đổi khí hậu', 'Bài viết nêu: \"a combination of habitat fragmentation, widespread pesticide use, and shifting climatic patterns\".', '{\"passage_title\":\"Global Pollinator Crisis\",\"passage_content\":\"Honeybees play a pivotal role in maintaining agricultural biodiversity by pollinating roughly one-third of the global food supply. However, apiaries worldwide are reporting unprecedented colony collapses. Ecologists point to a combination of habitat fragmentation, widespread pesticide use, and shifting climatic patterns as the primary drivers threatening their survival.\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(55, NULL, 'writing', 'A1', 1, NULL, 'essay_writing', 'Hãy viết 2-3 câu đơn giản (tối thiểu 20 từ) giới thiệu về một người bạn thân của bạn (tên, tuổi, sở thích chung).', '[]', NULL, 'My best friend is Nam. He is twenty years old. We love playing football and listening to music together on weekends.', 'Yêu cầu: giới thiệu tên, tuổi và sở thích chung, sử dụng thì hiện tại đơn chính xác.', '{\"min_words\":20,\"task_type\":\"Sentence Building & Personal Profile\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(56, NULL, 'writing', 'A1', 1, NULL, 'essay_writing', 'Hãy viết một ghi chú ngắn (tối thiểu 20 từ) nhắn người bạn cùng phòng mua giúp bạn một số đồ dùng (bánh mì, sữa, trứng).', '[]', NULL, 'Hi John, I am studying at the library right now. Can you please buy some bread, milk, and eggs on your way home? Thanks a lot!', 'Viết mẩu tin nhắn ngắn gọn, nêu rõ các món đồ cần nhờ mua và lời cảm ơn.', '{\"min_words\":20,\"task_type\":\"Short Informal Note\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(57, NULL, 'writing', 'A2', 1, NULL, 'essay_writing', 'Bạn vừa có một chuyến đi du lịch cuối tuần. Hãy viết một email ngắn (tối thiểu 35 từ) kể cho bạn bè nghe bạn đã đi đâu, thời tiết như thế nào và hoạt động bạn thích nhất.', '[]', NULL, 'Hi Sarah, last weekend I went to Da Nang with my family. The weather was very sunny and breezy. We swam at the beach and ate fresh seafood. I took a lot of photos that I will show you soon!', 'Sử dụng thì quá khứ đơn (went, was, swam, took), cấu trúc mạch lạc và đủ thông tin.', '{\"min_words\":35,\"task_type\":\"Informal Travel Email\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(58, NULL, 'writing', 'A2', 1, NULL, 'essay_writing', 'Hãy viết một email xin phép vắng mặt (tối thiểu 35 từ) gửi cho giáo viên tiếng Anh giải thích lý do bạn không thể tham gia buổi học vào ngày mai.', '[]', NULL, 'Dear Teacher Mary, I am writing to inform you that I cannot attend our English class tomorrow because I have a doctor appointment. I will ask my classmate for the homework notes and submit my assignment on time.', 'Giọng văn lịch sự, nêu rõ lý do vắng mặt và cam kết hoàn thành bài tập về nhà.', '{\"min_words\":35,\"task_type\":\"Formal Absence Request\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(59, NULL, 'writing', 'B1', 1, NULL, 'essay_writing', 'Viết một email phản hồi khách hàng (tối thiểu 50 từ) xin lỗi vì đơn hàng bị giao trễ 2 ngày và đưa ra phương án bồi thường (miễn phí vận chuyển hoặc giảm giá 15% cho đơn sau).', '[]', NULL, 'Dear Mr. Miller, Thank you for contacting our customer support team. We sincerely apologize for the unexpected delay in delivering your package. To compensate for this inconvenience, we have refunded your shipping fee and credited a 15% discount voucher to your account for your next purchase.', 'Email thư tín thương mại chuyên nghiệp: nhận lỗi chân thành, giải thích nguyên nhân và đưa ra giải pháp bồi hoàn cụ thể.', '{\"min_words\":50,\"task_type\":\"Customer Service Email\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(60, NULL, 'writing', 'B1', 1, NULL, 'essay_writing', 'Viết một đoạn văn ngắn (tối thiểu 50 từ) trình bày quan điểm của bạn về lợi ích và tác hại của việc sử dụng mạng xã hội đối với giới trẻ hiện nay.', '[]', NULL, 'Social media has transformed modern communication by allowing teenagers to connect globally and share educational resources effortlessly. However, excessive screen time often leads to digital distractions, anxiety, and a sedentary lifestyle. Therefore, cultivating healthy digital habits is vital for young users.', 'Bài viết có cấu trúc hai mặt: phân tích lợi ích kết nối và rủi ro xao nhãng kèm kết luận đề xuất giải pháp.', '{\"min_words\":50,\"task_type\":\"Opinion Paragraph\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(61, NULL, 'writing', 'B2', 1, NULL, 'essay_writing', 'Viết một đoạn văn học thuật (tối thiểu 70 từ) phân tích tầm quan trọng của năng lượng tái tạo (như điện mặt trời và gió) trong việc giảm biến đổi khí hậu toàn cầu.', '[]', NULL, 'Transitioning toward renewable energy sources, particularly solar and wind power, represents an imperative strategy to mitigate catastrophic climate change. Unlike fossil fuels, renewables emit virtually no greenhouse gases during operation, drastically shrinking national carbon footprints. Furthermore, investing in clean energy infrastructure stimulates economic growth, generates green employment opportunities, and enhances energy independence for developing economies.', 'Sử dụng từ vựng học thuật phong phú (mitigate, greenhouse gases, clean energy infrastructure, energy independence), câu ghép phức và liên từ lập luận chặt chẽ.', '{\"min_words\":70,\"task_type\":\"Academic Essay Excerpt\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(62, NULL, 'writing', 'C1', 1, NULL, 'essay_writing', 'Viết một đoạn văn phân tích chuyên sâu (tối thiểu 80 từ) về tác động của trí tuệ nhân tạo (AI) đối với thị trường lao động và yêu cầu tái đào tạo kỹ năng cho người lao động.', '[]', NULL, 'The accelerating integration of artificial intelligence across industries is profoundly restructuring labor paradigms. While automation inevitably displaces routine manual and cognitive roles, it concurrently catalyzes emerging occupations demanding advanced problem-solving, emotional intelligence, and technological literacy. Consequently, academic institutions and policymakers must proactively foster lifelong reskilling initiatives, thereby equipping the workforce to harmonize with intelligent automation rather than succumb to technological redundancy.', 'Đoạn văn đạt chuẩn C1 với từ ngữ tinh tế (restructuring labor paradigms, technological literacy, lifelong reskilling initiatives, technological redundancy).', '{\"min_words\":80,\"task_type\":\"High-level Critical Analysis\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(63, NULL, 'speaking', 'A1', 1, NULL, 'audio_recording', 'Đọc to câu chào hỏi và giới thiệu bản thân vào micro: \"Hello! My name is Alex. I come from Vietnam and I am happy to learn English.\"', '[]', NULL, 'Phát âm chuẩn ngữ điệu câu đơn giản, rõ âm đuôi /s/ trong Alex, /m/ trong Vietnam.', 'Tiêu chí: phát âm to rõ, không ngắc ngứ, trọng âm chuẩn.', '{\"task_type\":\"Read Aloud Drill\",\"prep_time\":10,\"speak_time\":20}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(64, NULL, 'speaking', 'A1', 1, NULL, 'audio_recording', 'Trả lời câu hỏi sau bằng micro (nói 1-2 câu): \"What do you usually have for breakfast?\"', '[]', NULL, 'I usually have bread and eggs with a cup of hot milk for breakfast.', 'Tiêu chí: phản xạ tự nhiên, nêu rõ món ăn sáng thường dùng.', '{\"task_type\":\"Short Daily Routine Response\",\"prep_time\":10,\"speak_time\":25}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(65, NULL, 'speaking', 'A2', 1, NULL, 'audio_recording', 'Ghi âm câu trả lời (nói trong 20-30 giây): \"Describe your favorite room in your house and explain why you like spending time there.\"', '[]', NULL, 'My favorite room is my bedroom because it is very quiet and comfortable. I have a large desk near the window where I study and read books every evening.', 'Tiêu chí: miêu tả căn phòng, đồ vật nổi bật và lý do yêu thích bằng câu nối mạch lạc.', '{\"task_type\":\"Room Description\",\"prep_time\":15,\"speak_time\":30}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(66, NULL, 'speaking', 'A2', 1, NULL, 'audio_recording', 'Tình huống tại nhà hàng: Ghi âm cuộc gọi đặt bàn (nói trong 20-30 giây): Đặt một bàn cho 4 người vào tối thứ Sáu lúc 7 giờ tối.', '[]', NULL, 'Good morning! I would like to reserve a table for four people this Friday evening at 7:00 PM, please. Could we have a table by the window?', 'Tiêu chí: giọng điệu lịch sự (would like to reserve), đầy đủ số người, ngày giờ và yêu cầu thêm.', '{\"task_type\":\"Restaurant Reservation Scenario\",\"prep_time\":15,\"speak_time\":30}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(67, NULL, 'speaking', 'B1', 1, NULL, 'audio_recording', 'Ghi âm câu trả lời (nói trong 30-45 giây): \"Some people prefer living in big cities, while others prefer living in the countryside. Which one do you prefer and why?\"', '[]', NULL, 'Personally, I prefer living in the countryside due to its serene atmosphere and fresher air. Unlike bustling urban centers where traffic congestion is frequent, the rural environment provides a peaceful pace of life.', 'Tiêu chí: nêu rõ lập trường so sánh thành thị vs nông thôn, đưa ra ít nhất 2 lý do thuyết phục kèm ví dụ.', '{\"task_type\":\"Comparison & Justification\",\"prep_time\":20,\"speak_time\":45}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(68, NULL, 'speaking', 'B1', 1, NULL, 'audio_recording', 'Xử lý tình huống công sở: Bạn trễ hạn nộp báo cáo cho sếp. Hãy ghi âm lời giải thích và cam kết thời gian nộp bù (nói trong 30-40 giây).', '[]', NULL, 'Hi Ms. Jennifer, I sincerely apologize for the delay in submitting the quarterly sales report. We encountered unexpected data errors yesterday, but I am currently finalizing the corrections and will email the completed document by 3:00 PM today.', 'Tiêu chí: xin lỗi chuyên nghiệp, giải thích ngắn gọn nguyên nhân và chốt thời hạn nộp chính xác.', '{\"task_type\":\"Workplace Crisis Communication\",\"prep_time\":20,\"speak_time\":45}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(69, NULL, 'speaking', 'B2', 1, NULL, 'audio_recording', 'Thuyết trình chủ đề (nói trong 45-60 giây): \"Do you think artificial intelligence will completely replace teachers in future classrooms? Explain your perspective.\"', '[]', NULL, 'In my view, while artificial intelligence can undoubtedly personalize learning paths and automate administrative grading, it will never entirely supplant human educators. Teachers cultivate empathy, moral values, and critical thinking—qualities that algorithms cannot replicate.', 'Tiêu chí: lập luận phản biện sắc sảo, sử dụng liên từ chỉ sự tương phản (while, undoubtedly, never entirely supplant) và phát âm lưu loát.', '{\"task_type\":\"Oral Debate & Academic Presentation\",\"prep_time\":30,\"speak_time\":60}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(70, NULL, 'speaking', 'C1', 1, NULL, 'audio_recording', 'Bình luận chuyên sâu (nói trong 60 giây): \"Discuss how globalization has influenced cultural identity in developing nations. Give specific insights.\"', '[]', NULL, 'Globalization has exerted a profound, multifaceted influence on developing societies. On one hand, it facilitates cross-cultural exchange and technological diffusion. On the other hand, the pervasive influx of Western media poses an existential threat to indigenous traditions and dialects, requiring deliberate cultural preservation policies.', 'Tiêu chí C1: vốn từ học thuật phong phú, khả năng triển khai luận điểm đa chiều (multifaceted influence, technological diffusion, existential threat to indigenous traditions).', '{\"task_type\":\"Advanced Cultural Commentary\",\"prep_time\":30,\"speak_time\":60}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(71, NULL, 'writing', 'A1', 1, NULL, 'essay_writing', 'TASK 1: Postcard to a Friend (At least 40 words)\n\nYou are on vacation at the beach. Write a short message to your friend Alex.\nIn your message, you should:\n- Tell Alex where you are\n- Describe the weather\n- Say what activities you did today', '[]', NULL, 'A completed postcard meeting all 3 bullet points with at least 40 words.', 'Đảm bảo viết đủ 3 ý: địa điểm kỳ nghỉ, thời tiết và các hoạt động đã làm.', '{\"part\":1,\"min_words\":40,\"task_type\":\"Postcard \\/ Short Message\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(72, NULL, 'writing', 'A2', 1, NULL, 'essay_writing', 'TASK 1: Email of Apology & Rescheduling (At least 80 words)\n\nYou promised to attend your friend\'s birthday party this Saturday, but you cannot come because of an unexpected exam.\nWrite an email to your friend:\n- Apologize for not being able to come\n- Explain why you are busy\n- Suggest another day to meet up next week', '[]', NULL, 'A well-formatted email with apology, reason, and alternative meeting suggestion.', 'Bố cục thư gồm: lời xin lỗi chân thành, lý do cụ thể và đề xuất cuộc hẹn bù vào tuần sau.', '{\"part\":1,\"min_words\":80,\"task_type\":\"Friendly Email\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(73, NULL, 'writing', 'B1', 1, NULL, 'essay_writing', 'TASK 1: Formal Request Letter (At least 120 words)\n\nYou are planning a study tour for your class to a local science museum. Write a letter to the museum manager:\n- Introduce yourself and your class\n- Inquire about ticket discounts for groups\n- Ask about guided tour schedules and special exhibitions', '[]', NULL, 'A formal inquiry letter with proper opening, 3 clear bullet points, and professional closing.', 'Sử dụng văn phong trang trọng (formal tone), diễn đạt rõ ràng các yêu cầu hỏi thông tin.', '{\"part\":1,\"min_words\":120,\"task_type\":\"Formal Letter\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(74, NULL, 'writing', 'B2', 1, NULL, 'essay_writing', 'TASK 2: Opinion Essay (At least 250 words)\n\nSome educators argue that students should be taught practical life skills (such as personal finance and cooking) at school alongside academic subjects. Others believe schools should focus solely on academic curriculum.\n\nDiscuss both views and give your own opinion. Provide reasons and examples from your knowledge or experience.', '[]', NULL, 'A well-structured 4-paragraph essay discussing both sides with relevant examples and clear thesis.', 'Bài luận cần có Mở bài (dẫn dắt + thesis), 2 Thân bài (phân tích 2 quan điểm đối lập), và Kết luận khẳng định quan điểm bản thân.', '{\"part\":2,\"min_words\":250,\"task_type\":\"Discussion Essay\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(75, NULL, 'writing', 'C1', 1, NULL, 'essay_writing', 'TASK 2: Critical Analytical Essay (At least 280 words)\n\nIn the era of artificial intelligence and automated decision-making algorithms, human critical judgment is more critical than ever. However, excessive reliance on AI systems might atrophy our cognitive faculties.\n\nEvaluate the ethical and intellectual implications of algorithmic dependence in contemporary higher education and professional workplaces. Propose sustainable frameworks for human-AI collaboration.', '[]', NULL, 'An insightful, advanced analytical essay with sophisticated vocabulary, nuanced argumentation, and cohesive transitions.', 'Yêu cầu lập luận đa chiều, từ vựng học thuật cao cấp C1 (e.g., algorithmic bias, cognitive atrophy, ethical governance).', '{\"part\":2,\"min_words\":280,\"task_type\":\"Analytical Essay\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(76, NULL, 'speaking', 'A1', 1, NULL, 'audio_recording', 'PART 1: My Family and Home (2 Minutes)\n\nPlease answer the following questions:\n1. Where do you live? Do you live in a house or an apartment?\n2. How many people are there in your family?\n3. What do you like doing together with your family on weekends?', '[]', NULL, 'audio_recording', 'Nói to rõ, trả lời đầy đủ 3 câu hỏi với câu hoàn chỉnh.', '{\"part\":1,\"prep_time\":30,\"duration\":120,\"task_type\":\"Social Interaction\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(77, NULL, 'speaking', 'A2', 1, NULL, 'audio_recording', 'PART 1: Shopping and Favorite Food (2 - 3 Minutes)\n\nPlease talk about your shopping habits and eating preferences:\n1. Do you prefer shopping online or in traditional stores? Why?\n2. What is your favorite dish and how often do you eat it?\n3. Do you enjoy cooking at home or eating out with friends?', '[]', NULL, 'audio_recording', 'Sử dụng các liên từ nối đơn giản (because, and, but, so) để phát triển câu trả lời.', '{\"part\":1,\"prep_time\":45,\"duration\":180,\"task_type\":\"Social Interaction\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(78, NULL, 'speaking', 'B1', 1, NULL, 'audio_recording', 'PART 2: Solution Discussion - Weekend Class Activity (3 - 4 Minutes)\n\nSituation: Your English class is planning an outdoor bonding activity for next Sunday. Three options are proposed:\n- Option 1: A picnic in the city central park\n- Option 2: A volunteer trip to an animal shelter\n- Option 3: A museum visit followed by a coffee workshop\n\nWhich option do you think is best for the class? Explain your choice and state why you rejected the other two options.', '[]', NULL, 'audio_recording', 'Cấu trúc bài nói: Chọn 1 phương án tối ưu, đưa ra 2 lý do ủng hộ và nêu lý do từ chối 2 phương án còn lại.', '{\"part\":2,\"prep_time\":60,\"duration\":180,\"task_type\":\"Solution Discussion\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(79, NULL, 'speaking', 'B2', 1, NULL, 'audio_recording', 'PART 3: Topic Development - Public Transportation in Smart Cities (4 - 5 Minutes)\n\nTopic: Enhancing public transit networks yields significant societal benefits.\n- Environmental preservation (emission reduction)\n- Economic efficiency (less traffic congestion)\n- Social equity (affordable mobility for all citizens)\n\nPresent your ideas clearly, expand on the suggested points, and answer: How can governments encourage more private car owners to switch to public transit?', '[]', NULL, 'audio_recording', 'Thuyết trình có cấu trúc: Giới thiệu chủ đề, phân tích từng luận điểm với ví dụ thực tế và giải quyết câu hỏi mở rộng.', '{\"part\":3,\"prep_time\":60,\"duration\":240,\"task_type\":\"Topic Development\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(80, NULL, 'speaking', 'C1', 1, NULL, 'audio_recording', 'PART 3: In-depth Oral Discourse - The Ethics of Climate Engineering (4 - 5 Minutes)\n\nTopic: Geoengineering technologies (such as solar radiation management and ocean fertilization) are being advocated to counteract global warming.\n\nElaborate on the scientific promises versus systemic risks of climate intervention. In your discourse, evaluate:\n- Geopolitical governance and moral hazard\n- Unintended ecological consequences\n- The imperative of equitable international consensus', '[]', NULL, 'audio_recording', 'Bài nói học thuật nâng cao C1: lập luận sâu sắc, mạch lạc, sử dụng các cấu trúc câu phức và thuật ngữ chuyên sâu.', '{\"part\":3,\"prep_time\":60,\"duration\":240,\"task_type\":\"Topic Development\"}', '2026-09-07 09:00:29', '2026-09-07 09:00:29', NULL),
(81, NULL, 'reading', 'B2', 1, NULL, 'mcq', 'What is the primary objective of deploying IoT sensors in smart urban transit systems?', '[\"To optimize real-time traffic flow and diminish transit congestion\",\"To replace human drivers across all public bus routes immediately\",\"To restrict citizen movements during peak commercial hours\",\"To increase municipal parking fees throughout downtown districts\"]', NULL, 'To optimize real-time traffic flow and diminish transit congestion', 'The passage notes that IoT sensors monitor congestion dynamically to optimize signal timings and reduce transit gridlock.', '{\"passage_title\":\"Smart Cities: The IoT Urban Revolution\",\"passage_content\":\"Smart cities utilize an extensive matrix of Internet of Things (IoT) sensors, cloud computing, and real-time data analytics to overhaul municipal infrastructure. Within transportation networks, smart traffic lights respond dynamically to vehicle density, effectively trimming commuter delays and urban emissions. Furthermore, predictive maintenance systems monitor bridge integrity and water pipelines, averting costly catastrophic structural failures before they materialize.\",\"testlet_badge\":\"Ch\\u1eb7ng 2: B2 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(82, NULL, 'reading', 'B2', 1, NULL, 'mcq', 'According to the passage, how do predictive maintenance systems enhance city infrastructure?', '[\"By identifying potential structural defects prior to severe failures\",\"By constructing additional bridges without architectural permits\",\"By privatizing public water utility management networks\",\"By automating tax collection procedures for civil construction\"]', NULL, 'By identifying potential structural defects prior to severe failures', 'The text highlights that predictive maintenance monitors integrity to avert catastrophic failures before they happen.', '{\"passage_title\":\"Smart Cities: The IoT Urban Revolution\",\"passage_content\":\"Smart cities utilize an extensive matrix of Internet of Things (IoT) sensors, cloud computing, and real-time data analytics to overhaul municipal infrastructure. Within transportation networks, smart traffic lights respond dynamically to vehicle density, effectively trimming commuter delays and urban emissions. Furthermore, predictive maintenance systems monitor bridge integrity and water pipelines, averting costly catastrophic structural failures before they materialize.\",\"testlet_badge\":\"Ch\\u1eb7ng 2: B2 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(83, NULL, 'reading', 'B2', 1, NULL, 'mcq', 'The word \\\"overhaul\\\" in the first sentence is closest in meaning to:', '[\"thoroughly renovate and modernize\",\"slowly demolish and abandon\",\"strictly limit the usage of\",\"temporarily relocate outside\"]', NULL, 'thoroughly renovate and modernize', 'To overhaul means to examine, repair, and comprehensively upgrade or renovate an existing system.', '{\"passage_title\":\"Smart Cities: The IoT Urban Revolution\",\"passage_content\":\"Smart cities utilize an extensive matrix of Internet of Things (IoT) sensors, cloud computing, and real-time data analytics to overhaul municipal infrastructure. Within transportation networks, smart traffic lights respond dynamically to vehicle density, effectively trimming commuter delays and urban emissions. Furthermore, predictive maintenance systems monitor bridge integrity and water pipelines, averting costly catastrophic structural failures before they materialize.\",\"testlet_badge\":\"Ch\\u1eb7ng 2: B2 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL);
INSERT INTO `question_banks` (`id`, `course_id`, `skill`, `difficulty`, `version`, `parent_id`, `question_type`, `question_text`, `options`, `audio_url`, `correct_answer`, `explanation`, `meta_data`, `created_at`, `updated_at`, `deleted_at`) VALUES
(84, NULL, 'reading', 'B2', 1, NULL, 'mcq', 'Which environmental dividend directly stems from smart traffic management?', '[\"Reduction of vehicle exhaust emissions\",\"Immediate elimination of urban noise pollution\",\"Complete conversion of all vehicles to solar electricity\",\"Expansion of downtown residential parks\"]', NULL, 'Reduction of vehicle exhaust emissions', 'The passage states smart traffic lights trim commuter delays and urban emissions.', '{\"passage_title\":\"Smart Cities: The IoT Urban Revolution\",\"passage_content\":\"Smart cities utilize an extensive matrix of Internet of Things (IoT) sensors, cloud computing, and real-time data analytics to overhaul municipal infrastructure. Within transportation networks, smart traffic lights respond dynamically to vehicle density, effectively trimming commuter delays and urban emissions. Furthermore, predictive maintenance systems monitor bridge integrity and water pipelines, averting costly catastrophic structural failures before they materialize.\",\"testlet_badge\":\"Ch\\u1eb7ng 2: B2 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(85, NULL, 'reading', 'B1', 1, NULL, 'mcq', 'Where were wild coffee plants originally discovered according to historical accounts?', '[\"The Ethiopian highlands\",\"The South American rainforests\",\"The Arabian peninsula coastlines\",\"Central European valleys\"]', NULL, 'The Ethiopian highlands', 'Legend and botanical history trace the origin of Coffea arabica to the ancient forests of the Ethiopian plateau.', '{\"passage_title\":\"The Global Journey of Coffee\",\"passage_content\":\"Coffee originated in the ancient wild forests of the Ethiopian plateau, where local goat herders first observed its invigorating effects. By the fifteenth century, coffee cultivation and trade were thriving across the Arabian Peninsula. In sixteenth-century Europe, coffeehouses quickly earned the moniker \'penny universities\' because for the price of a penny, patrons could engage in lively intellectual discourse, read news bulletins, and forge business partnerships.\",\"testlet_badge\":\"Ch\\u1eb7ng 1: B1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(86, NULL, 'reading', 'B1', 1, NULL, 'mcq', 'Why were early European coffeehouses nicknamed \\\"penny universities\\\"?', '[\"Customers could gain knowledge and engage in scholarly debate for a penny\",\"Universities charged a penny to admit coffee merchants\",\"Only certified university professors were permitted to purchase coffee\",\"Books were auctioned inside coffeehouses for one penny each\"]', NULL, 'Customers could gain knowledge and engage in scholarly debate for a penny', 'The text explains that for a penny, patrons could join intellectual discourse and learn news, hence the nickname.', '{\"passage_title\":\"The Global Journey of Coffee\",\"passage_content\":\"Coffee originated in the ancient wild forests of the Ethiopian plateau, where local goat herders first observed its invigorating effects. By the fifteenth century, coffee cultivation and trade were thriving across the Arabian Peninsula. In sixteenth-century Europe, coffeehouses quickly earned the moniker \'penny universities\' because for the price of a penny, patrons could engage in lively intellectual discourse, read news bulletins, and forge business partnerships.\",\"testlet_badge\":\"Ch\\u1eb7ng 1: B1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(87, NULL, 'reading', 'B1', 1, NULL, 'mcq', 'The word \\\"invigorating\\\" in the first sentence most nearly means:', '[\"energizing and stimulating\",\"relaxing and sleep-inducing\",\"poisonous and bitter\",\"mysterious and frightening\"]', NULL, 'energizing and stimulating', 'Invigorating means giving life, energy, or vitality to someone.', '{\"passage_title\":\"The Global Journey of Coffee\",\"passage_content\":\"Coffee originated in the ancient wild forests of the Ethiopian plateau, where local goat herders first observed its invigorating effects. By the fifteenth century, coffee cultivation and trade were thriving across the Arabian Peninsula. In sixteenth-century Europe, coffeehouses quickly earned the moniker \'penny universities\' because for the price of a penny, patrons could engage in lively intellectual discourse, read news bulletins, and forge business partnerships.\",\"testlet_badge\":\"Ch\\u1eb7ng 1: B1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(88, NULL, 'reading', 'B1', 1, NULL, 'mcq', 'What did patrons commonly do inside seventeenth-century coffeehouses besides drinking coffee?', '[\"Read news bulletins and establish commercial partnerships\",\"Conduct surgical procedures under supervision\",\"Compete in professional athletic tournaments\",\"Manufacture printing presses for universities\"]', NULL, 'Read news bulletins and establish commercial partnerships', 'The passage states patrons engaged in lively intellectual discourse, read news bulletins, and forged business partnerships.', '{\"passage_title\":\"The Global Journey of Coffee\",\"passage_content\":\"Coffee originated in the ancient wild forests of the Ethiopian plateau, where local goat herders first observed its invigorating effects. By the fifteenth century, coffee cultivation and trade were thriving across the Arabian Peninsula. In sixteenth-century Europe, coffeehouses quickly earned the moniker \'penny universities\' because for the price of a penny, patrons could engage in lively intellectual discourse, read news bulletins, and forge business partnerships.\",\"testlet_badge\":\"Ch\\u1eb7ng 1: B1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(89, NULL, 'reading', 'C1', 1, NULL, 'mcq', 'What makes hydrothermal vent ecosystems fundamentally distinct from terrestrial biomes?', '[\"They derive primary metabolic energy from chemosynthesis rather than solar photosynthesis\",\"They completely lack multicellular organisms and predatory species\",\"Their water temperatures remain constantly near freezing points year-round\",\"They are immune to anthropogenic climate disruption and mineral mining\"]', NULL, 'They derive primary metabolic energy from chemosynthesis rather than solar photosynthesis', 'Hydrothermal communities thrive on mineral-rich fluids metabolized by chemosynthetic bacteria rather than sunlight.', '{\"passage_title\":\"Abyssal Ecology and Deep-Sea Geopolitics\",\"passage_content\":\"The bathypelagic abyss, once deemed a sterile wasteland, harbors extraordinarily biodiverse biomes centered around hydrothermal vents. In total darkness and under crushing hydrostatic pressure, chemosynthetic microorganisms convert dissolved hydrogen sulfide into organic sustenance, nurturing endemic tube worms and crustaceans. However, prospective seabed mining targeting polymetallic nodules threatens to obliterate these fragile benthic niches before science can document their full enzymatic potential.\",\"testlet_badge\":\"Ch\\u1eb7ng 3: C1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(90, NULL, 'reading', 'C1', 1, NULL, 'mcq', 'According to the author, prospective seabed mining poses an acute risk because:', '[\"It threatens to eradicate benthic ecosystems before their biological mechanisms are thoroughly understood\",\"It will deplete all global reserves of polymetallic nodules within five years\",\"It causes immediate tsunamis along coastal continental shelves\",\"It replaces traditional surface shipping with automated submarines\"]', NULL, 'It threatens to eradicate benthic ecosystems before their biological mechanisms are thoroughly understood', 'The author cautions that seabed mining threatens to obliterate these fragile niches before science can document their enzymatic potential.', '{\"passage_title\":\"Abyssal Ecology and Deep-Sea Geopolitics\",\"passage_content\":\"The bathypelagic abyss, once deemed a sterile wasteland, harbors extraordinarily biodiverse biomes centered around hydrothermal vents. In total darkness and under crushing hydrostatic pressure, chemosynthetic microorganisms convert dissolved hydrogen sulfide into organic sustenance, nurturing endemic tube worms and crustaceans. However, prospective seabed mining targeting polymetallic nodules threatens to obliterate these fragile benthic niches before science can document their full enzymatic potential.\",\"testlet_badge\":\"Ch\\u1eb7ng 3: C1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(91, NULL, 'reading', 'C1', 1, NULL, 'mcq', 'The word \\\"benthic\\\" in the concluding sentence refers to:', '[\"organisms living on or near the ocean floor\",\"surface-dwelling migratory pelagic birds\",\"shallow coral reef fish varieties\",\"atmosphere-filtering plankton species\"]', NULL, 'organisms living on or near the ocean floor', 'Benthic refers to the lowest ecological zone of a body of water, including the sediment surface and sub-surface layers.', '{\"passage_title\":\"Abyssal Ecology and Deep-Sea Geopolitics\",\"passage_content\":\"The bathypelagic abyss, once deemed a sterile wasteland, harbors extraordinarily biodiverse biomes centered around hydrothermal vents. In total darkness and under crushing hydrostatic pressure, chemosynthetic microorganisms convert dissolved hydrogen sulfide into organic sustenance, nurturing endemic tube worms and crustaceans. However, prospective seabed mining targeting polymetallic nodules threatens to obliterate these fragile benthic niches before science can document their full enzymatic potential.\",\"testlet_badge\":\"Ch\\u1eb7ng 3: C1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(92, NULL, 'reading', 'C1', 1, NULL, 'mcq', 'What was the historical perception of the deep bathypelagic zone prior to modern exploration?', '[\"It was presumed to be a barren and virtually lifeless expanse\",\"It was considered the primary nursery for pelagic tuna fisheries\",\"It was charted accurately by sixteenth-century navigators\",\"It was believed to produce most atmospheric oxygen\"]', NULL, 'It was presumed to be a barren and virtually lifeless expanse', 'The text states the abyss was \\\"once deemed a sterile wasteland\\\" before discovery of its biodiversity.', '{\"passage_title\":\"Abyssal Ecology and Deep-Sea Geopolitics\",\"passage_content\":\"The bathypelagic abyss, once deemed a sterile wasteland, harbors extraordinarily biodiverse biomes centered around hydrothermal vents. In total darkness and under crushing hydrostatic pressure, chemosynthetic microorganisms convert dissolved hydrogen sulfide into organic sustenance, nurturing endemic tube worms and crustaceans. However, prospective seabed mining targeting polymetallic nodules threatens to obliterate these fragile benthic niches before science can document their full enzymatic potential.\",\"testlet_badge\":\"Ch\\u1eb7ng 3: C1 Reading\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(93, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Đọc bảng chỉ dẫn tại sân bay: \\\"BAGGAGE CLAIM - Carousels 1 to 4 downstairs\\\". Hành khách cần đi đâu để lấy hành lý?', '[\"\\u0110i xu\\u1ed1ng t\\u1ea7ng d\\u01b0\\u1edbi\",\"L\\u00ean t\\u1ea7ng tr\\u00ean\",\"Ra b\\u00e3i \\u0111\\u1ed7 xe b\\u00ean ngo\\u00e0i\",\"\\u0110\\u1ebfn c\\u1ed5ng ki\\u1ec3m so\\u00e1t an ninh\"]', NULL, 'Đi xuống tầng dưới', '\\\"Downstairs\\\" có nghĩa là đi xuống tầng dưới.', '{\"passage_title\":\"Airport Sign\",\"passage_content\":\"AIRPORT INFORMATION:\\\\nBAGGAGE CLAIM\\\\nCarousels 1 to 4 downstairs.\\\\nElevators located on your right.\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(94, NULL, 'reading', 'A2', 1, NULL, 'mcq', 'Đọc thông báo tiệm giặt ủi: \\\"Express Service: Clothes dropped off before 10:00 AM will be ready by 5:00 PM on the same day.\\\" Muốn lấy đồ giặt trong ngày, khách cần gửi trước mấy giờ?', '[\"Tr\\u01b0\\u1edbc 10:00 AM\",\"Tr\\u01b0\\u1edbc 12:00 PM\",\"Tr\\u01b0\\u1edbc 2:00 PM\",\"Tr\\u01b0\\u1edbc 5:00 PM\"]', NULL, 'Trước 10:00 AM', 'Thông báo nêu: \\\"dropped off before 10:00 AM will be ready by 5:00 PM on the same day\\\".', '{\"passage_title\":\"Laundry Express Notice\",\"passage_content\":\"QUICK CLEAN LAUNDROMAT\\\\nExpress Service:\\\\nClothes dropped off before 10:00 AM will be ready by 5:00 PM on the same day.\\\\nStandard Service: 24-hour turnaround.\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(95, NULL, 'reading', 'A2', 1, NULL, 'mcq', 'Đọc email mời phỏng vấn: \\\"Please confirm your availability for an online interview via Zoom on Thursday at 2:00 PM.\\\" Ứng viên được hẹn phỏng vấn vào lúc nào và qua hình thức nào?', '[\"Th\\u1ee9 N\\u0103m l\\u00fac 2:00 PM qua Zoom\",\"Th\\u1ee9 S\\u00e1u l\\u00fac 2:00 PM t\\u1ea1i v\\u0103n ph\\u00f2ng\",\"Th\\u1ee9 N\\u0103m l\\u00fac 10:00 AM qua \\u0111i\\u1ec7n tho\\u1ea1i\",\"Th\\u1ee9 Hai l\\u00fac 2:00 PM qua Skype\"]', NULL, 'Thứ Năm lúc 2:00 PM qua Zoom', 'Thư ghi rõ: \\\"online interview via Zoom on Thursday at 2:00 PM\\\".', '{\"passage_title\":\"Interview Invitation Email\",\"passage_content\":\"Dear Applicant,\\\\nThank you for applying to our marketing position. We are pleased to invite you for the first interview round. Please confirm your availability for an online interview via Zoom on Thursday at 2:00 PM.\"}', '2026-09-07 09:08:09', '2026-09-07 09:08:09', NULL),
(96, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Read the official announcement regarding \'Job Interview & Workplace Communication\': \'All participants are required to submit their feedback by Friday afternoon.\' What must participants do?', '[\"Hand in their opinions before the weekend\",\"Register for the meeting on Monday\",\"Cancel their registration immediately\",\"Pay an additional evaluation fee\"]', NULL, 'Hand in their opinions before the weekend', 'Trong ngữ cảnh \'Job Interview & Workplace Communication\', \'submit their feedback by Friday afternoon\' đồng nghĩa với \'Hand in their opinions before the weekend\'.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(97, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'In a formal email about \'Job Interview & Workplace Communication\', which phrase is most professional for closing?', '[\"Sincerely yours,\",\"Cheers buddy,\",\"Talk to you later,\",\"See ya soon,\"]', NULL, 'Sincerely yours,', '\'Sincerely yours\' là lời kết thư trang trọng và lịch sự nhất trong thư từ trao đổi chuyên nghiệp.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(98, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Select the most accurate synonym for the underlined term in \'Job Interview & Workplace Communication\': \'The proposed strategy has proved remarkably EFFECTIVE.\'', '[\"Productive and successful\",\"Extremely expensive\",\"Complicated to execute\",\"Unreliable and risky\"]', NULL, 'Productive and successful', '\'Effective\' có nghĩa là mang lại hiệu quả cao, đồng nghĩa với \'Productive and successful\'.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(99, NULL, 'reading', 'A1', 1, NULL, 'mcq', '[AUDIO] Listen to the dialogue: \'— Could you tell me where the seminar on Job Interview & Workplace Communication takes place? — It has been moved to Hall 4B.\' Where is the seminar held?', '[\"In Hall 4B\",\"In the main lobby\",\"Online via video conference\",\"It has been cancelled\"]', NULL, 'In Hall 4B', 'Người nói khẳng định hội thảo về \'Job Interview & Workplace Communication\' đã được chuyển sang phòng \'Hall 4B\'.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(100, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Choose the sentence with correct subject-verb agreement related to \'Job Interview & Workplace Communication\':', '[\"Neither the manager nor the staff members were aware of the schedule change.\",\"Neither the manager nor the staff members was aware of the schedule change.\",\"Neither the manager nor the staff members are knowing the schedule change.\",\"Neither the manager nor the staff members is aware of the schedule change.\"]', NULL, 'Neither the manager nor the staff members were aware of the schedule change.', 'Với cấu trúc \'Neither... nor...\', động từ chia theo danh từ gần nhất (\'the staff members\' là số nhiều -> dùng \'were\').', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(101, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Complete the sentence appropriately: \'Due to unforeseen challenges in Job Interview & Workplace Communication, the organizing committee decided to ___ the conference until next month.\'', '[\"postpone\",\"accelerate\",\"prohibit\",\"distribute\"]', NULL, 'postpone', '\'Postpone\' (hoãn lại) là từ phù hợp nhất với ngữ cảnh hoãn hội nghị đến tháng sau.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(102, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'What is the primary message of this notice? \'Notice: In observance of the upcoming holiday, our Job Interview & Workplace Communication division will operate with reduced hours.\'', '[\"Working hours will be shorter than usual due to the holiday\",\"The department is closing down permanently\",\"All employees must work overtime during the holiday\",\"Services will remain completely unchanged\"]', NULL, 'Working hours will be shorter than usual due to the holiday', '\'Operate with reduced hours\' chỉ thời gian làm việc được rút ngắn lại so với thông thường.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(103, NULL, 'reading', 'A1', 1, NULL, 'mcq', '[AUDIO] Conversation excerpt: \'— How often do you review the progress of Job Interview & Workplace Communication? — We hold a progress evaluation meeting on a bi-weekly basis.\' How often is the meeting?', '[\"Every two weeks\",\"Twice every day\",\"Once a month\",\"Every six months\"]', NULL, 'Every two weeks', '\'Bi-weekly\' trong ngữ cảnh quản lý dự án có nghĩa là 2 tuần một lần (Every two weeks).', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(104, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Identify the best concluding sentence for an essay discussing the key advantages of \'Job Interview & Workplace Communication\':', '[\"In conclusion, mastering Job Interview & Workplace Communication provides sustainable long-term benefits for career development.\",\"Anyway, I don\'t really care much about Job Interview & Workplace Communication because it seems hard.\",\"Secondly, we should also mention something totally unrelated to the prompt.\",\"That is all I know about Job Interview & Workplace Communication and I will stop writing here.\"]', NULL, 'In conclusion, mastering Job Interview & Workplace Communication provides sustainable long-term benefits for career development.', 'Câu kết luận chuẩn học thuật cần tóm lược luận điểm và nhấn mạnh giá trị cốt lõi một cách trang trọng.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(105, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Which question is most suitable to ask an expert during a panel discussion on \'Job Interview & Workplace Communication\'?', '[\"What innovative methodologies do you recommend to enhance efficiency in Job Interview & Workplace Communication?\",\"Do you like eating breakfast before coming to this seminar today?\",\"Why is the microphone so loud in this auditorium right now?\",\"Can you tell me what time the cafeteria closes tonight?\"]', NULL, 'What innovative methodologies do you recommend to enhance efficiency in Job Interview & Workplace Communication?', 'Câu hỏi mang tính học thuật và thực tiễn trực tiếp liên quan đến phương pháp cải tiến chủ đề \'Job Interview & Workplace Communication\'.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:06:09', '2026-09-07 17:06:09'),
(106, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'According to the latest industry review on \'Job Interview & Workplace Communication\', organizations that adopt modern practices experience a significant boost in productivity. What is the observed outcome of adopting modern practices in \'Job Interview & Workplace Communication\'?', '[\"Substantial enhancement in overall productivity\",\"An immediate increase in operational errors\",\"A decrease in team collaboration\",\"Complete stagnation in development\"]', NULL, 'Substantial enhancement in overall productivity', '\'Significant boost in productivity\' đồng nghĩa với \'Substantial enhancement in overall productivity\'.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(107, NULL, 'reading', 'A1', 1, NULL, 'mcq', '[AUDIO] Speaker: \'When preparing for a comprehensive assessment in Job Interview & Workplace Communication, time management is just as crucial as subject knowledge.\' According to the speaker, what factor is equally important as subject knowledge?', '[\"Effective management of time\",\"Having advanced computer software\",\"Finishing questions in under ten minutes\",\"Memorizing definitions without understanding\"]', NULL, 'Effective management of time', '\'Time management is just as crucial\' khẳng định quản lý thời gian quan trọng tương đương kiến thức chuyên môn.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(108, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Choose the most appropriate collocation: \'The executive committee agreed to ___ rigorous standards for Job Interview & Workplace Communication.\' Which verb best completes the collocation?', '[\"implement\",\"refuse\",\"evaporate\",\"disguise\"]', NULL, 'implement', '\'Implement rigorous standards\' (áp dụng/triển khai các tiêu chuẩn nghiêm ngặt) là cụm từ chuyên môn chuẩn xác.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(109, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'In an academic debate regarding \'Job Interview & Workplace Communication\', an interlocutor states: \'There is compelling evidence that collaboration yields superior outcomes.\' What does \'compelling evidence\' imply?', '[\"Strong and convincing proof\",\"Doubtful and unverified claims\",\"Confusing experimental results\",\"Irrelevant background trivia\"]', NULL, 'Strong and convincing proof', '\'Compelling evidence\' nghĩa là bằng chứng thuyết phục, rõ ràng và có căn cứ vững chắc.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(110, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Identify the error in the following statement about Job Interview & Workplace Communication: \'Despite of the strict guidelines, many candidates managed to finish on time.\' Which part of the sentence contains a grammatical error?', '[\"\'Despite of\' (should be \'Despite\' or \'In spite of\')\",\"\'the strict guidelines\'\",\"\'managed to finish\'\",\"\'on time\'\"]', NULL, '\'Despite of\' (should be \'Despite\' or \'In spite of\')', '\'Despite\' không đi với giới từ \'of\'. Cần dùng \'Despite + N\' hoặc \'In spite of + N\'.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(111, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'A workshop memo on Job Interview & Workplace Communication announces: \'The hands-on session is limited to 20 attendees on a first-come, first-served basis.\' How will participants be admitted to the session?', '[\"In the order of their registration until full\",\"By random lottery selection only\",\"Based on seniority in the organization\",\"Only candidates with doctoral degrees\"]', NULL, 'In the order of their registration until full', '\'First-come, first-served\' mang ý nghĩa ai đăng ký trước sẽ được ưu tiên trước cho đến khi đủ số lượng.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(112, NULL, 'reading', 'A1', 1, NULL, 'mcq', '[AUDIO] Dialog: \'— I am struggling with the technical terminology in Job Interview & Workplace Communication. — Why don\'t you review the glossaries attached in chapter 3?\' What advice does the second speaker give?', '[\"Consult the glossary list in chapter 3\",\"Drop the course immediately\",\"Ignore technical terms entirely\",\"Translate every single sentence into another language\"]', NULL, 'Consult the glossary list in chapter 3', 'Người thứ hai khuyên nên tra cứu bảng chú giải thuật ngữ (\'glossary\') ở chương 3.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(113, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Select the most cohesive transition word: \'The team encountered unexpected obstacles in Job Interview & Workplace Communication. ___, they delivered the project ahead of schedule.\' Which transition word best expresses contrast?', '[\"Nevertheless\",\"Furthermore\",\"Consequently\",\"Similarly\"]', NULL, 'Nevertheless', '\'Nevertheless\' (Tuy nhiên / Mặc dù vậy) thể hiện sự tương phản rõ nét giữa khó khăn ban đầu và kết quả thành công.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(114, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'Which of the following sentences regarding Job Interview & Workplace Communication demonstrates the most concise and formal writing style? Choose the most professional sentence:', '[\"The department evaluated three proposals before reaching a final decision.\",\"The department kind of looked at three things and then made up its mind.\",\"We did a whole bunch of thinking about stuff and decided eventually.\",\"Lots of people thought about things and then decided what to do next.\"]', NULL, 'The department evaluated three proposals before reaching a final decision.', 'Câu thứ nhất sử dụng từ vựng chuẩn xác (\'evaluated\', \'proposals\', \'reaching a final decision\') và cấu trúc trang trọng.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(115, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'In an evaluation of \'Job Interview & Workplace Communication\', what does the phrase \'benchmark against global standards\' mean? Explain the meaning of \'benchmark against global standards\':', '[\"Compare performance against established international criteria\",\"Ignore all international regulations\",\"Set lower expectations for domestic teams\",\"Copy competitors without verification\"]', NULL, 'Compare performance against established international criteria', '\'Benchmark against\' có nghĩa là đối chiếu, so sánh hiệu suất với chuẩn mực đã được công nhận trên toàn cầu.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
(116, NULL, 'reading', 'A1', 1, NULL, 'mcq', 'According to the latest industry review on \'Job Interview & Workplace Communication\', organizations that adopt modern practices experience a significant boost in productivity. What is the observed outcome of adopting modern practices in \'Job Interview & Workplace Communication\'? [Set 2]', '[\"Substantial enhancement in overall productivity\",\"An immediate increase in operational errors\",\"A decrease in team collaboration\",\"Complete stagnation in development\"]', NULL, 'Substantial enhancement in overall productivity', '\'Significant boost in productivity\' đồng nghĩa với \'Substantial enhancement in overall productivity\'.', NULL, '2026-09-07 16:47:47', '2026-09-07 17:05:52', '2026-09-07 17:05:52'),
